		public void Close(global::UnityEngine.Events.UnityAction<global::Dpr.UI.UIWindow> onClosed_, global::UIWindowID nextWindowId) {
            if (_coClose != null)
                return;

            if (_boxTray != null)
                BoxWork.SetCurrentTray(_boxTray.Param.paramIndex);

            BoxWork.SetStatusPut((int)_statusType);
            _input.inputEnabled = false;
            _isControlEnable = false;
            isCancelFormChange = true;
            _coClose = SmartPoint.AssetAssistant.Sequencer.Start(OpClose(onClosed_, nextWindowId));
        }
		private global::System.Collections.IEnumerator OpClose(global::UnityEngine.Events.UnityAction<global::Dpr.UI.UIWindow> onClosed_, global::UIWindowID nextWindowId) {
            bool isModelClosed;

            CloseMessageWindow();
            if (_formChangeEffectInstance != null)
            {
                _formChangeEffectInstance.Stop(0.0f, true);
                _formChangeEffectInstance = null;
            }

            if (_coOpen == null)
                Audio.AudioManager.Instance.PlaySe(AK.EVENTS.S_ME048, null);

            while (_coOpen != null)
                yield return null;

            _input.inputEnabled = false;
            _isControlEnable = false;
            _statusPanel.Close();
            isModelClosed = false;
            SetModelPanel(false, false, () => isModelClosed = true);
            while (!isModelClosed)
                yield return null;

            if (_modelView != null)
            {
                _modelView.Clear(true);
                _modelView = null;
            }

            SmartPoint.AssetAssistant.Sequencer.update -= OnUpdate;
            onPreClose?.Invoke(this);
            yield return OpPlayCloseWindowAnimationAndWaiting(nextWindowId);

            _hideIconIndexes = null;
            _swapIcons = null;
            _existSwapIndexes = null;
            _messageParam = null;
            _messageWindow = null;
            _keyguideParam = null;
            _matSearchButton = null;
            UIManager.Instance._ReleaseUIWindow(this);
            if (_isDuckOn && !_param.isDontDuckOffBGM)
                Audio.AudioManager.Instance.SetBgmEvent(AK.EVENTS.DUCKOFF_BGM, false);

            onClosed_?.Invoke(this);
            _coClose = null;
        }
