		private void ApplyPokemonStatusAndModel(global::Pml.PokePara.PokemonParam param, bool isImmidiate = false, bool isPlateEnable = true) {
            if (_statusPanel == null)
                return;

            bool isStatusShown = _statusPanel.SetUp(_statusType, param);
            SetTradeInfo(!isStatusShown);
            if (_statusType == StatusType.None)
            {
                SetModelPanel(param != null, isImmidiate);
                if (param != null)
                    ApplyModel(param, false);
            }
            _currentPokeParam = param;
        }
		private void SetModelPanel(bool isEnable, bool isImmediate = false, global::System.Action callBack = null) {
            if (_modelSideRoot.localPosition.x == (isEnable ? _modelOpenPosX : _modelClosePosX))
            {
                callBack?.Invoke();
                return;
            }

            if (!isImmediate)
            {
                SetPanelTransitionSide(gameObject, _modelSideRoot, isEnable ? _modelOpenPosX : _modelClosePosX, callBack);
                return;
            }

            _modelSideRoot.transform.localPosition = new Vector3(isEnable ? _modelOpenPosX : _modelClosePosX, _modelSideRoot.transform.localPosition.y, _modelSideRoot.transform.localPosition.z);
            callBack?.Invoke();
        }
		private void SetTrayNamePlate(global::Dpr.UI.UINavigator navigator) {
            if (_namePlate == null)
                return;

            bool isEnable = false;
            if (navigator.userParam is NaviParam naviParam && naviParam.itemType == NaviParam.ItemType.Tray)
            {
                var naviItem = GetNaviItem(navigator);
                if (naviItem.pokemonParam != null)
                {
                    _namePlate.Setup(naviItem.pokemonParam, navigator);
                    isEnable = true;
                }
            }
            _namePlate.SetActive(isEnable);
        }
