		private void SetSelectBoxPanel(bool isEnable, global::System.Nullable<int> index = default) {
            SetPanelTransitionBoth(gameObject, _partyTrayRoot, isEnable ? _partyClosePosX : _partyOpenPosX, _partyTrayCanvasGroup, isEnable ? 0.0f : 1.0f);
            SetPanelTransitionSide(gameObject, _boxTrayRoot, isEnable ? _boxTraySlideX : _boxTrayPosX);
            if (isEnable)
            {
                _statusPanel.Close();
                SetModelPanel(false, false);
                SetTradeInfo(true);
                // 01cb7868: raw BoxInfinityScroll +0x44 read = the zero-caller GetParamIndex() inlined (brief lesson 72)
                _currentTrayIndex = _trayScroll.GetParamIndex();
                _returnNavigator = _navigator;
                _boxListPanel.Open(() =>
                {
                    var navigates = _boxListPanel.CurrentNavigates;
                    navigates.Initialize(BoxWork.GetOpenTrayMax(), _multiNavis[(int)MultiNaviType.BoxLook], _multiNavis[(int)MultiNaviType.BoxSearch]);
                    _navigator = index.HasValue ? _boxListPanel.CurrentNavigates.NavigatorList[index.Value] : _multiNavis[(int)MultiNaviType.BoxLook];
                    SetCursor(false);
                    SetSwapRootParent();
                    if (_currentTrayIndex == _fromTrayIndex)
                        ApplyCurrentTrayAtBoxList();
                });
            }
            else
            {
                _currentTrayIndex = _trayScroll.GetParamIndex();
                _navigator = _returnNavigator;
                SetCursor(false);
                _boxListPanel.Close(() =>
                {
                    SetSwapRootParent();
                    if (IsSwap())
