		private void SetupKeyguide() {
            if (_isForceClosing)
                return;

            if (_keyguideParam == null)
                _keyguideParam = new Keyguide.Param();
            else
                _keyguideParam.itemParams.Clear();

            // byte jump table @03d5b9da
            switch (_controlType)
            {
                case ControlType.SelectPoke:
                {
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_TOP_DECIDE });
                    if (_param.openType == OpenType.Normal)
                        _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_TOP_MODESWITCH });

                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_TOP_OPERATIONSWITCH });
                    var naviItem = GetNaviItem(_navigator);
                    PokemonParam pokemonParam = naviItem == null ? null : naviItem.pokemonParam;
                    // 01cb80e0: IsSwap() inlined (its flag 0xdca)
                    if (IsSwap())
                        pokemonParam = _currentPokeParam;

                    if (pokemonParam != null)
                    {
                        if (_statusType == StatusType.Status && FlagWork.GetFlag(Dpr.EvScript.EvWork.FLAG_INDEX.FE_D31R0201_JUDGE_TALK) && !pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
                            _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_TOP_JUDGE });
                        else
                            _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_TOP_STATUS });
                    }
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_TOP_BACK });
                    break;
                }
                case ControlType.SelectBox:
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_LIST_DECIDE });
                    if (!_param.isDisableUseful)
                        _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_LIST_USEFUL });

                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_LIST_BACK });
                    break;
                case ControlType.SetMark:
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_TOP_MARKING });
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_TOP_BACK });
                    break;
                case ControlType.SelectWallPaper:
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_TOP_DECIDE });
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_TOP_BACK });
                    break;
                case ControlType.SelectSearch:
                case ControlType.SelectSearchSub:
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_SEARCH_DECIDE });
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_SEARCH_RESET });
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_SEARCH_FIND });
                    _keyguideParam.itemParams.Add(new KeyguideItem.Param { keyguideId = KeyguideID.BOX_SEARCH_BACK });
                    break;
            }

            var keyguide = UIManager.Instance.GetKeyguide(null, true);
            keyguide.transform.SetParent(transform, false);
            keyguide.Setup(_keyguideParam);
        }
