		public static void LimitBox(bool enabled) {
            _limitBoxRefCount += enabled ? 1 : -1;
            // 01cb8810: isLimitBox getter inlined (flag 0xdcb)
            if (isLimitBox)
            {
                var windows = UIManager.Instance.GetExistWindows<BoxWindow>();
                // 01cb88f8: ExecCloseForce (flag-less, 0 callers, placed right after) inlined
                for (int i = 0; i < windows.Count; i++)
                    windows[i].ExecCloseForce();
            }
        }
		private bool IsCheckCloseForce() {
            if (_isForceClosing)
                return false;

            if (isLimitBox)
                return true;

            if (UIManager.Instance.GetExistWindowCount<BoxWindow>() > 1)
                return UIManager.Instance.GetExistWindow<BoxWindow>() == this;

            return false;
        }
		private void ExecCloseForce() {
            if (_isForceClosing)
                return;

            _isControlEnable = false;
            _isForceClosing = true;
            _input.inputEnabled = false;
            if (_coClose == null)
                Close(null, _prevWindowId);
        }
		private void OnUpdate(float deltaTime) {
            if (IsCheckCloseForce())
            {
                // 01cb8b64: ExecCloseForce (flag-less, 0 callers) inlined
                ExecCloseForce();
                return;
            }

            if (UIManager.Instance.GetCurrentUIWindow<UIWindow>() != this)
                return;

            if (!_isControlEnable)
                return;

            if (IsPanelTrasition || _battleTeamScroll.IsMoving || _trayScroll.IsMoving)
                return;

            if (_twSequence != null)
            {
                if (_twSequence.IsActive())
                {
                    if (_twSequence.IsPlaying())
                        return;
                }
                else
                {
                    _twSequence = null;
                }
            }

            if (UpdateNetworkTrade(deltaTime))
                return;

            if (_messageWindow != null && _messageWindow.IsEnabledInput)
                return;

            // byte jump table @03d5b9e0
            switch (_controlType)
            {
                case ControlType.SelectPoke:
                    if (UpdateFunctionButton(deltaTime))
                        return;

                    if (UpdatePlusMinusButton(deltaTime))
                        return;

                    // 01cb8d2c: IsSwap() inlined (flag 0xdca)
                    if (IsSwap())
                    {
                        if (UpdateSwap())
                            return;
                    }
                    else
                    {
                        if (UpdateTray(deltaTime))
                            return;
                    }

                    UpdateSelect(deltaTime, () =>
                    {
                        if (IsSwap())
                            return;

                        ApplyPokemonStatusAndModel(_navigator, false, true);
                        SetupKeyguide();
                    });
                    break;
                case ControlType.SelectBox:
                    if (UpdateFunctionButton(deltaTime))
                        return;

                    if (UpdateBoxList(deltaTime))
                        return;

                    UpdateSelect(deltaTime, () =>
                    {
                        if (_navigator != _multiNavis[(int)MultiNaviType.BoxLook] && _navigator != _multiNavis[(int)MultiNaviType.BoxSearch])
                            return;

