		public void SetOtherPokeParam(global::Pml.PokePara.PokemonParam param, int cassetVersion) {
            string parentName = null;
            param.SetNickName(Dpr.SubContents.Utils.CheckNGPokeName(param));
            parentName = param.GetParentName();
            param.SetParentName(Dpr.SubContents.Utils.CheckNGTrainerName(ref parentName, (MessageEnumData.MsgLangId)param.GetLangId(), cassetVersion));
            var tradePokeParam = new PokemonParam(param);
            if (tradePokeParam.IsEgg(EggCheckType.BOTH_EGG))
            {
                uint year = tradePokeParam.GetMemories(Memories.EGG_TAKEN_YEAR);
                uint month = tradePokeParam.GetMemories(Memories.EGG_TAKEN_MONTH);
                uint day = tradePokeParam.GetMemories(Memories.EGG_TAKEN_DAY);
                uint place = tradePokeParam.GetMemories(Memories.EGG_TAKEN_PLACE);
                tradePokeParam.SetMemories(Memories.FIRST_CONTACT_YEAR, year);
                tradePokeParam.SetMemories(Memories.FIRST_CONTACT_MONTH, month);
                tradePokeParam.SetMemories(Memories.FIRST_CONTACT_DAY, day);
                tradePokeParam.SetMemories(Memories.FIRST_CONTACT_PLACE, place);
            }
            else
            {
                poketool.poke_memo.poketool_poke_memo.ClearPlaceTime(tradePokeParam, poketool.poke_memo.DataType.DATA_TYPE_EGG_TAKEN);
            }
            _tradeParam.otherOriginalParam = param;
            _tradeParam.otherPokeParam = tradePokeParam;
        }
