            if (_toNavigators.Count < _existSwapIndexes.Count)
            {
                Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
                return false;
            }

            NaviParam.ItemType fromItemType = fromNaviParam.itemType;
            Audio.AudioManager.Instance.PlaySe(AK.EVENTS.S_ME055, null);
            _trayScroll.Jump(toTrayIndex);
            _input.inputEnabled = false;
            if (fromItemType == NaviParam.ItemType.Party)
            {
                MoveRangeTrayByParty();
            }
            else
            {
                int trayIndex;
                int count = 0;
                foreach (int index in _existSwapIndexes)
                {
                    UINavigator fromNavigator = IsRangeSwap() ? _fromNavigators[index] : _fromNavigator;
                    int pos = (fromNavigator.userParam as NaviParam).index;
                    int pos2 = (_toNavigators[count].userParam as NaviParam).index;
                    BoxPokemonWork.GetPokemon(_fromTrayIndex, pos);
                    BoxPokemonWork.MovePokemon(_fromTrayIndex, pos, toTrayIndex, pos2, 1, 1, new PokemonParam());
                    BoxWork.ChangePokemon(_fromTrayIndex, pos, toTrayIndex, pos2);
                    Dpr.BallDeco.BallDecoWork.MoveCapsuleExtraData(_fromTrayIndex, pos, toTrayIndex, pos2);
                    count++;
                }

                trayIndex = _currentTrayIndex;
                _trayScroll.Apply(_trayScroll.GetParamIndex(), null, _param, _searchData, _selected);
                RestoreRangeSelect(true, false, true, null, () => _currentTrayIndex = trayIndex);
            }

            _swapIcon.SetActive(false);
            if (IsRangeSwap())
            {
                int iconCount = _fromNavigators.Count;
                for (int i = 0; i < iconCount; i++)
                    _swapIcons[i].SetActive(false);
            }
            _numberPlate.SetActive(false);
            return true;
        }
		private void BackTrayByBoxlist() {
            _trayScroll.Apply(_currentTrayIndex, _fromTrayIndex == _currentTrayIndex ? _hideIconIndexes : null, _param, _searchData, _selected);
            _trayScroll.Jump(_currentTrayIndex);
