		private void UpdateSelect(float deltaTime, global::UnityEngine.Events.UnityAction onMoveComplete = null) {
            if (IsRepeatButton(UIManager.StickLLeft | UIManager.StickLRight, false) && IsRepeatButton(UIManager.StickLUp | UIManager.StickLDown, false))
                return;

            int teamDir = 0;
            int trayDir = 0;
            UINavigator.NavigateType dir = UINavigator.NavigateType.None;

            if (_navigator == _naviPartySelect && _displayMode == DisplayMode.Battle)
            {
                teamDir = IsRepeatButton(UIManager.StickLLeft, false) ? -1 : 0;
                if (IsRepeatButton(UIManager.StickLRight, false))
                    teamDir = 1;
            }
            else if (_navigator == _multiNavis[(int)MultiNaviType.BoxSelect])
            {
                trayDir = IsRepeatButton(UIManager.StickLLeft, false) ? -1 : 0;
                if (IsRepeatButton(UIManager.StickLRight, false))
                    trayDir = 1;
            }
            else
            {
                if (IsPushButton(UIManager.StickLRight, false))
                    dir = UINavigator.NavigateType.Right;
                else if (IsRepeatButton(UIManager.StickLRight, false) && !_navigator.IsStop(UINavigator.NavigateType.Right))
                    dir = _isRepeatCancel ? UINavigator.NavigateType.None : UINavigator.NavigateType.Right;

                if (IsPushButton(UIManager.StickLLeft, false))
                    dir = UINavigator.NavigateType.Left;
                else if (IsRepeatButton(UIManager.StickLLeft, false) && !_navigator.IsStop(UINavigator.NavigateType.Left) && !_isRepeatCancel)
                    dir = UINavigator.NavigateType.Left;
            }

            if (IsPushButton(UIManager.StickLDown, false))
                dir = UINavigator.NavigateType.Bottom;
            else if (IsRepeatButton(UIManager.StickLDown, false) && !_navigator.IsStop(UINavigator.NavigateType.Bottom) && !_isRepeatCancel)
                dir = UINavigator.NavigateType.Bottom;

            if (IsPushButton(UIManager.StickLUp, false))
                dir = UINavigator.NavigateType.Top;
            else if (IsRepeatButton(UIManager.StickLUp, false) && !_navigator.IsStop(UINavigator.NavigateType.Top) && !_isRepeatCancel)
                dir = UINavigator.NavigateType.Top;

            if (dir == UINavigator.NavigateType.None)
            {
                int pageDir = IsPushButton(GameController.ButtonMask.L, false) ? -1 : 0;
                if (IsPushButton(GameController.ButtonMask.R, false))
                    pageDir = 1;

                if (pageDir != 0)
                {
                    NaviParam naviParam = _navigator.userParam as NaviParam;
                    if (_displayMode == DisplayMode.Battle && (_navigator == _naviPartySelect || (naviParam != null && naviParam.itemType == NaviParam.ItemType.Party)))
                        teamDir = pageDir;
                    else
                        trayDir = pageDir;
                }

                if (teamDir != 0)
                {
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SLIDE, null);
                    int teamCount = _battleTeamScroll.baseParams.Count;
#if !SWITCH
                    // s46: the Switch's integer division (0 divisor -> 0 / dividend), PcIntDiv
                    int teamIndex = global::PcPlatform.PcIntDiv.Rem(teamCount + teamDir + _battleTeamScroll.GetParamIndex(), teamCount);
#else
                    int teamIndex = (teamCount + teamDir + _battleTeamScroll.GetParamIndex()) % teamCount;
#endif
                    _battleTeamScroll.Apply(teamIndex, null, _param, _searchData, _selected);
                    if (_fromNavigator != null && _fromTeamIndex == teamIndex && (_fromNavigator.userParam as NaviParam).itemType == NaviParam.ItemType.Party)
                        _battleTeamScroll.SetSelect(teamIndex, _hideIconIndexes);
                    _battleTeamScroll.Move(teamDir, onMoveComplete);
                    if (_fromNavigator == null)
                        _currentTeamIndex = teamIndex;
                    if (teamDir < 0)
                        UITweener.PlayArrowTween(_partyArrows[0].GetComponent<RectTransform>(), UITweener.ArrowDirection.Left);
                    else
                        UITweener.PlayArrowTween(_partyArrows[1].GetComponent<RectTransform>(), UITweener.ArrowDirection.Right);
                }

                if (_displayMode == DisplayMode.Battle && _fromNavigator != null)
                    trayDir = 0;

                if (trayDir == 0 || _controlType == ControlType.SelectBox || _boxListPanel.SelectedIndex >= 0)
                    return;

                Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_SLIDE, null);
                int trayCount = _trayScroll.baseParams.Count;
#if !SWITCH
                // s46: the Switch's integer division (0 divisor -> 0 / dividend), PcIntDiv
                int trayIndex = global::PcPlatform.PcIntDiv.Rem(trayCount + trayDir + _trayScroll.GetParamIndex(), trayCount);
#else
                int trayIndex = (trayCount + trayDir + _trayScroll.GetParamIndex()) % trayCount;
#endif
                List<int> hideIndexes = null;
                if (_fromNavigator != null && (_fromNavigator.userParam as NaviParam).itemType == NaviParam.ItemType.Tray)
                    hideIndexes = _fromTrayIndex == trayIndex ? _hideIconIndexes : null;
                _trayScroll.Apply(trayIndex, hideIndexes, _param, _searchData, _selected);
                _trayScroll.Move(trayDir, onMoveComplete);
                if (_fromNavigator == null)
                    _currentTrayIndex = trayIndex;
                if (trayDir < 0)
                    UITweener.PlayArrowTween(_trayArrows[0].GetComponent<RectTransform>(), UITweener.ArrowDirection.Left);
                else
                    UITweener.PlayArrowTween(_trayArrows[1].GetComponent<RectTransform>(), UITweener.ArrowDirection.Right);
                return;
            }

            bool isMoved = SetNavigate(dir, null, true);
            _isRepeatCancel = false;
            if ((_displayMode == DisplayMode.Battle && _fromNavigator != null) || _boxListPanel.SelectedIndex >= 0)
            {
                if (isMoved)
                {
                    if (SetNavigate(dir, _navigator, false))
                        SetNavigate(dir, _navigator, false);
                }
                else if (_navigator.GetNavigate(dir) as BoxMultiNavigator != null)
                {
                    _isRepeatCancel = true;
                }
            }

            onMoveComplete?.Invoke();
        }
