		private void SetDisplayMode(global::Dpr.UI.BoxWindow.DisplayMode displayMode) {
            _displayMode = displayMode;
            _displayTitle.transform.SetSiblingIndex((int)_displayMode + 1);
            _displayModeText.SetupMessage(null, _displayModeLabels[(int)displayMode]);
            if (_displayMode == DisplayMode.Battle)
            {
                _partyNormal.SetActive(false);
                _battleTeamScroll.SetActive(true);
