            _trayScroll.SetDisplayMode(_displayMode);
            _trayScroll.Apply(_currentTrayIndex, _hideIconIndexes, _param, _searchData, _selected);
            _trayScroll.Jump(_currentTrayIndex);
            // 01cbf5a4: GetCurrentParty() (part 2, 0 `bl` callers) inlined
            var party = GetCurrentParty();
            party.Apply(null, _param, _searchData, _selected);
            party.SetupItems();
