		private bool SetNavigate(global::Dpr.UI.UINavigator.NavigateType dirType, global::Dpr.UI.UINavigator navigator = null, bool isSE = true) {
            switch (_controlType)
            {
                case ControlType.SelectPoke:
                    if (IsRangeSwap())
                        return SetRangeNavigateInTray(dirType, isSE);
                    return SetNavigateInTray(dirType, navigator, isSE);
                case ControlType.SelectBox:
                    return SetNavigateBoxSelect(dirType, navigator, isSE);
                default:
                    return false;
            }
        }
		private bool SetNavigateInTray(global::Dpr.UI.UINavigator.NavigateType dirType, global::Dpr.UI.UINavigator navigator = null, bool isSE = true) {
            if (navigator != null)
                _navigator = navigator;

            if (dirType != UINavigator.NavigateType.None)
            {
                if (_navigator == null)
                    return false;

                UINavigator next = _navigator.GetNavigate(dirType);
                if (next == null)
                    return false;

                if (IsRangeSelecting() && _cursorCanvas.transform.parent.transform.parent != next.transform.parent)
                    return false;

                _navigator = next;
                SetNavigateFunction(dirType);
            }

            SetCursor(isSE);
            SetSelectIcons(dirType);
            return _navigator as BoxMultiNavigator != null;
        }
		private bool SetRangeNavigateInTray(global::Dpr.UI.UINavigator.NavigateType dirType, bool isSE = true) {
            if (dirType == UINavigator.NavigateType.None)
                return false;

            if (_navigator == null)
                return false;

            UINavigator next = _navigator.GetNavigate(dirType);
            if (next == null)
                return false;

            NaviParam nextParam = next.userParam as NaviParam;
            UINavigator current = _navigator;
            NaviParam currentParam = current.userParam as NaviParam;
            if (nextParam != null)
            {
                bool isTrayToParty = (currentParam == null || currentParam.itemType == NaviParam.ItemType.Tray) && nextParam.itemType == NaviParam.ItemType.Party;
                bool isPartyToTray = currentParam != null && currentParam.itemType == NaviParam.ItemType.Party && nextParam.itemType == NaviParam.ItemType.Tray;
                if ((isTrayToParty || isPartyToTray) && _rangeWidth != 1)
                    return false;
            }

            _navigator = next;
            SetNavigateFunction(dirType);
            float offsetX = nextParam != null && nextParam.itemType == NaviParam.ItemType.Party ? _cursorPartyOffsetX : _cursorOffsetX;
            _cursorBody.localPosition = new Vector3(offsetX, _cursorBody.localPosition.y, 0f);
            SetCursor(isSE);

            RectTransform rangeTransform = _rangeCursor.rectTransform;
            float x = rangeTransform.position.x + (next.transform.position.x - current.transform.position.x);
            float y = rangeTransform.position.y + (next.transform.position.y - current.transform.position.y);
            rangeTransform.position = new Vector3(x, y);

            bool isMulti = _navigator as BoxMultiNavigator != null;
            bool isNumberPlate = isMulti || _navigator == _naviPartySelect;
            _numberPlate.SetActive(isNumberPlate);
            _rangePlate.SetActive(!isNumberPlate);
            return isMulti;
        }
		private void SetNavigateFunction(global::Dpr.UI.UINavigator.NavigateType dirType) {
            NaviParam naviParam = _navigator.userParam as NaviParam;
            if (naviParam != null && naviParam.itemType == NaviParam.ItemType.Tray)
                _lastNaviBoxTrayItem = _navigator;

            BoxMultiNavigator multiNavigator = _navigator as BoxMultiNavigator;
            if (multiNavigator == null)
                return;

            int lastIndex = _lastNaviBoxTrayItem != null ? (_lastNaviBoxTrayItem.userParam as NaviParam).index : 0;
            if (multiNavigator == _multiNavis[(int)MultiNaviType.UnitLook] || multiNavigator == _multiNavis[(int)MultiNaviType.UnitSearch])
            {
                int index;
                if (dirType == UINavigator.NavigateType.Left)
                    index = 2;
                else if (dirType == UINavigator.NavigateType.Right)
                    index = 0;
                else
                    index = Mathf.Clamp((lastIndex - (multiNavigator == _multiNavis[(int)MultiNaviType.UnitLook] ? 0 : 3)) % TrayCellWidth, 0, 2);

                multiNavigator.SetNavigate(UINavigator.NavigateType.Top, index);
                _lastNaviBoxTrayItem = multiNavigator.top;
            }
            else if (dirType == UINavigator.NavigateType.Top || dirType == UINavigator.NavigateType.Bottom)
            {
                int index = lastIndex % TrayCellWidth;
                multiNavigator.SetNavigate(UINavigator.NavigateType.Bottom, index);
                multiNavigator.SetNavigate(UINavigator.NavigateType.Top, index > 2 ? 1 : 0);
            }
        }
		private bool SetNavigateBoxSelect(global::Dpr.UI.UINavigator.NavigateType type, global::Dpr.UI.UINavigator navigator, bool isSE = true) {
            if (navigator != null)
                _navigator = navigator;

            bool result = false;
            if (type != UINavigator.NavigateType.None)
            {
                if (_navigator == null)
                    return false;

                UINavigator next = _navigator.GetNavigate(type);
                if (next == null)
                    return false;

                _navigator = next;
                NaviParam naviParam = _navigator.userParam as NaviParam;
                if (naviParam != null && naviParam.itemType == NaviParam.ItemType.Box)
                    _lastNaviBoxTrayItem = _navigator;

                BoxMultiNavigator multiNavigator = _navigator as BoxMultiNavigator;
                if (multiNavigator != null)
                {
                    int width = _boxListPanel.CurrentNavigates.Width;
                    int half = width / 2;
                    int lastIndex = _lastNaviBoxTrayItem != null ? (_lastNaviBoxTrayItem.userParam as NaviParam).index : 0;
                    int offset = multiNavigator == _multiNavis[(int)MultiNaviType.BoxLook] ? 0 : half;
                    // unguarded sdiv/msub @01cc259c: a zero width yields lastIndex on ARM64 (C# would throw)
                    int column = (width != 0 ? lastIndex % width : lastIndex) - offset;
                    int count = half;
                    if (width - half * 2 > 0 && (column >= half || column < 0))
                        count++;

                    int index;
                    if (type == UINavigator.NavigateType.Left)
                        index = count - 1;
                    else if (type == UINavigator.NavigateType.Right)
                        index = 0;
                    else
                        // unguarded sdiv/msub @01cc25dc: a zero count yields column on ARM64 (C# would throw)
                        index = count != 0 ? column % count : column;

                    if (index < 0)
                        index = 0;

