                    multiNavigator.SetNavigate(UINavigator.NavigateType.Bottom, index);
                    _lastNaviBoxTrayItem = multiNavigator.top;
                    result = true;
                }
                else if (_fromNavigator != null && (_fromNavigator.userParam as NaviParam).itemType == NaviParam.ItemType.Tray)
                {
                    int trayIndex = naviParam.index;
                    int fromTrayIndex = _fromTrayIndex;
                    _trayScroll.Apply(trayIndex, null, _param, _searchData, _selected);
                    _trayScroll.Jump(naviParam.index);
                    if (fromTrayIndex == trayIndex)
                        ApplyTrayAtBoxList();
                }
                else
                {
                    _trayScroll.Apply(naviParam.index, null, _param, _searchData, _selected);
                    _trayScroll.Jump(naviParam.index);
                }
            }

            SetCursor(isSE);
            SetSelectIcons(type);
            return result;
        }
