                yield break;

            yield return null;

            bool isValid = param != null && param.GetMonsNo() != MonsNo.NULL;
            if (_modelView != null)
            {
                if (isValid)
                {
                    _modelView.Setup(new PokemonModelView.Param
                    {
                        type = UIModelViewController.ModelViewType.Box,
                        pokemonParam = param,
                        canvas = _canvas,
                    });
                }
                else
                {
                    _modelView.Clear(false);
                }
            }
        }
