            _namePlate.SetActive(false);
            _numberPlate.Setup(count);
            _matSearchButton.SetFloat(Shader.PropertyToID("_GrayscaleAmount"), 1.0f);
            _rangePlate.SetActive(true);
            RectTransform rangeCursorRect = _rangeCursor.rectTransform;
            _rangePlate.rectTransform.sizeDelta = new Vector3(_trayCellSizeX * _rangeWidth, _trayCellSizeY * _rangeHeight, 0.0f);
            Transform itemTransform = GetNaviItem(_navigator).transform;
            float offsetX = naviParam.itemType == NaviParam.ItemType.Party ? -90.0f : 4.0f;
#if !SWITCH
            // offsetX, the cell sizes (rect units) and the select lift in world pixels (PcUiRoot.UnitScale; 1 at 720p)
            float unit = PcPlatform.PcUiRoot.UnitScale(this);
            _rangePlate.rectTransform.position = new Vector3(itemTransform.position.x + (offsetX - _trayCellSizeX * 0.5f) * unit, itemTransform.position.y + (_trayCellSizeY * 0.5f + BoxItem._selectIconOffset.y) * unit);
#else
            _rangePlate.rectTransform.position = new Vector3(offsetX + (itemTransform.position.x - _trayCellSizeX * 0.5f), itemTransform.position.y + _trayCellSizeY * 0.5f + BoxItem._selectIconOffset.y);
#endif
            SetRangeIcons(_fromNavigators);
            ApplyPokemonStatusAndModel(_navigator, false, false);
        }
		private void SetRangeIcons(global::System.Collections.Generic.List<global::Dpr.UI.UINavigator> navigators) {
            Color color = _rangeCursor.color;
            color.a = 0f;
            _rangeCursor.color = color;
            _hideIconIndexes.Clear();
            for (int i = 0; i < navigators.Count; i++)
            {
                BoxItem naviItem = GetNaviItem(navigators[i]);
                PokemonIcon swapRoot = naviItem.GetSwapRoot();
                PokemonParam pokemonParam = naviItem.pokemonParam;
                Vector3 position;
                if (pokemonParam != null)
                {
                    _swapIcons[i].Copy(swapRoot);
                    position = navigators[i].transform.position;
                    _hideIconIndexes.Add((navigators[i].userParam as NaviParam).index);
                }
                else
                {
                    _swapIcons[i].SetActive(false);
                    _swapIcons[i].monsIcon.sprite = null;
                    position = _navigator.transform.position;
                }

                _swapIcons[i].transform.SetParent(_rangePlate.transform);
                _swapIcons[i].transform.position = position;
            }

            SetIconSelect(_swapIcons, navigators, true, true, null);
            _cursor.transform.SetAsFirstSibling();
        }
		private void GetRangeFromNavigators(ref global::System.Collections.Generic.List<global::Dpr.UI.UINavigator> recieveList, global::Dpr.UI.UINavigator startNavi) {
            List<UINavigator> navigators = new List<UINavigator>(30);
            int width = Math.Abs(_rangeX) + 1;
            int height = Math.Abs(_rangeY) + 1;
            UINavigator lineNavigator = startNavi;
            for (int y = 0; y < height; y++)
            {
                UINavigator navigator = lineNavigator;
                for (int x = 0; x < width; x++)
                {
                    navigators.Add(navigator);
                    if (_rangeX > 0)
                        navigator = navigator.right;
                    else
                        navigator = navigator.left;
                }

                if (_rangeY > 0)
                    lineNavigator = lineNavigator.bottom;
                else
                    lineNavigator = lineNavigator.top;
            }

            navigators.Sort((x, y) => (x.userParam as NaviParam).index - (y.userParam as NaviParam).index);

            int minX = width;
            int maxX = 0;
            int minY = height;
            int maxY = 0;
            for (int i = 0; i < navigators.Count; i++)
            {
                if (GetNaviItem(navigators[i]).pokemonParam != null)
                {
#if !SWITCH
                    // s46: the Switch's integer division (0 divisor -> 0 / dividend), PcIntDiv
                    int x = global::PcPlatform.PcIntDiv.Rem(i, width);
                    int y = global::PcPlatform.PcIntDiv.Div(i, width);
#else
                    int x = i % width;
                    int y = i / width;
#endif
                    if (minX > x)
                        minX = x;
                    if (maxX < x)
                        maxX = x;
                    if (minY > y)
                        minY = y;
                    if (maxY < y)
                        maxY = y;
                }
            }

            _existSwapIndexes.Clear();
            if (recieveList != null)
                recieveList.Clear();
            else
                recieveList = new List<UINavigator>(30);

            for (int i = 0; i < navigators.Count; i++)
            {
#if !SWITCH
                // s46: the Switch's integer division (0 divisor -> 0 / dividend), PcIntDiv
                int x = global::PcPlatform.PcIntDiv.Rem(i, width);
                int y = global::PcPlatform.PcIntDiv.Div(i, width);
#else
                int x = i % width;
                int y = i / width;
#endif
                if (x >= minX && x <= maxX && y >= minY && y <= maxY)
                {
                    recieveList.Add(navigators[i]);
                    if (GetNaviItem(navigators[i]).pokemonParam != null)
                        _existSwapIndexes.Add(recieveList.Count - 1);
                }
            }

            _rangeWidth = maxX - minX + 1;
            _rangeHeight = maxY - minY + 1;
        }
		private bool GetRangeToNavigators(ref global::System.Collections.Generic.List<global::Dpr.UI.UINavigator> recieveList, global::Dpr.UI.UINavigator selectNavi, global::System.Collections.Generic.List<global::Dpr.UI.UINavigator> fromTargetList, global::Dpr.UI.BoxInfinityScrollItem fromTray = null) {
            if (recieveList == null)
                recieveList = new List<UINavigator>(30);
            else
                recieveList.Clear();

            NaviParam naviParam = selectNavi.userParam as NaviParam;
            NaviParam.ItemType itemType = naviParam.itemType;
            int index = naviParam.index;
            bool isFromParty = fromTray as BoxParty != null;
            int rowMax = itemType == NaviParam.ItemType.Tray ? 5 : 6;
            int row = itemType == NaviParam.ItemType.Tray ? index / 6 : index;
            int fromIndex = 0;
            UINavigator rowNavi = selectNavi;
            for (int y = 0; y < _rangeHeight; y++)
            {
                if (row + y >= rowMax)
                    return false;

                UINavigator navi = rowNavi;
                for (int x = 0; x < _rangeWidth; x++)
                {
                    UINavigator fromNavi = fromTargetList[fromIndex];
                    if (itemType == NaviParam.ItemType.Tray)
                    {
                        if (index % 6 + x > 5)
                            return false;

                        int pos = (fromNavi.userParam as NaviParam).index;
                        if (isFromParty)
                        {
                            if (_displayMode != DisplayMode.Battle && GetPartyPokemonParam(pos) != null && GetNaviItem(navi).pokemonParam != null)
                                return false;
                        }
                        else
                        {
                            bool isExist = BoxPokemonWork.CheckPokemon(_fromTrayIndex, pos, true) && GetNaviItem(navi).pokemonParam != null;
                            if (_fromTrayIndex == _boxTray.Param.paramIndex)
                                isExist &= !fromTargetList.Contains(navi);
                            if (isExist)
                                return false;
                        }
                    }
                    else if (_displayMode != DisplayMode.Battle && !fromTargetList.Contains(navi))
                    {
                        int memberCount = _displayMode == DisplayMode.Battle ? BoxWork.GetTeamPokeCount(_battleTeam.Param.paramIndex) : (int)PlayerWork.playerParty.GetMemberCount();
                        if ((navi.userParam as NaviParam).index < memberCount)
                            return false;
                    }

                    recieveList.Add(navi);
                    navi = navi.right;
                    fromIndex++;
                }
                rowNavi = rowNavi.bottom;
            }
            return true;
        }
		private void UpdatePokemonPaaram(int trayIndex, int index, global::Pml.PokePara.PokemonParam param) {
            if (trayIndex >= 0)
                BoxPokemonWork.UpdatePokemon(param, trayIndex, index);
            else
                PlayerWork.playerParty.ReplaceMember((byte)index, param);
        }
		private global::Dpr.UI.BoxItem GetNaviItem(global::Dpr.UI.UINavigator navigator) {
            if (navigator == null)
                return null;

            if (!(navigator.userParam is NaviParam naviParam))
                return null;

            switch (naviParam.itemType)
            {
                case NaviParam.ItemType.Party:
                    // 01cb6f08: GetCurrentParty() (part 2, 0 callers) inlined
                    return GetCurrentParty().Items[naviParam.index];
                case NaviParam.ItemType.Tray:
                    return _boxTray.Items[naviParam.index];
                default:
                    return null;
            }
        }
		private global::Dpr.UI.BoxParty GetCurrentParty() {
            return _displayMode == DisplayMode.Battle ? _battleTeam : _partyNormal;
        }
