		private void ApplyTrayAtBoxList() {
            if (_fromNavigator != null && _hideIconIndexes.Count > 0)
            {
                foreach (int index in _hideIconIndexes)
                    _boxTray.Items[index].GetSwapRoot().monsIcon.color = new Color32(255, 255, 255, 140);
