		private void ApplyTray(bool isParty) {
            if (isParty)
            {
                if (_displayMode == DisplayMode.Battle)
                {
                    _battleTeamScroll.Apply(_currentTeamIndex, _hideIconIndexes, _param, _searchData, _selected);
                    _battleTeamScroll.Jump(_currentTeamIndex);
                }
                else
                {
                    _partyNormal.Apply(_hideIconIndexes, _param, _searchData, _selected);
                    _partyNormal.SetupItems();
                }
            }
            else
            {
                List<int> hideIndexes = _fromNavigator != null && _fromTrayIndex < 0 ? null : _hideIconIndexes;
                _trayScroll.Apply(_currentTrayIndex, hideIndexes, _param, _searchData, _selected);
                _trayScroll.Jump(_currentTrayIndex);
            }
        }
