		public global::System.Collections.IEnumerator DebugNext(int waitSec = 0, global::Dpr.UI.BoxWindow.NetTradePhase phase = (global::Dpr.UI.BoxWindow.NetTradePhase)(0), global::System.Action callback = null) {
            bool isBreak = false;
            System.Diagnostics.Stopwatch sw = new System.Diagnostics.Stopwatch();
            sw.Start();
            yield return null;

            while (!isBreak)
            {
                isBreak = IsPushButton(UIManager.ButtonA) || (waitSec > 0 && sw.ElapsedMilliseconds > waitSec * 1000);
                yield return null;
            }

            sw.Stop();
            callback?.Invoke();
            ToNextPhase(phase);
        }
