		private void OpenContextMenu() {
            NaviParam naviParam = _navigator.userParam as NaviParam;
            var menuItems = new List<ContextMenuItem.Param>();
            if (_navigator == _multiNavis[(int)MultiNaviType.BoxSelect])
            {
                if (_param.openType != OpenType.Normal)
                {
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
                    return;
                }

                SetMessage("SS_box_061", true, null, null, false);
                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_JUMP });
                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_WALLPAPER });
                if (_param.isEnableKeyboard)
                    menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_NAME });
                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_CANCEL });
            }
            else
            {
                BoxItem item = GetNaviItem(_navigator);
                switch (_displayMode)
                {
                    case DisplayMode.Battle:
                        if (_navigator == _naviPartySelect && _param.isEnableKeyboard)
                        {
                            SetMessage("SS_box_102", true, null, null, false);
                            OpenYesNoContextMenu(menuItem =>
                            {
                                _messageWindow.CloseWindow();
                                _messageWindow = null;
                                if (menuItem.param.menuId == ContextMenuID.BOX_YES)
                                {
                                    var keyboardParam = new SoftwareKeyboard.Param();
                                    keyboardParam.text = BoxWork.GetTeamName(_battleTeam.Param.paramIndex);
                                    keyboardParam.textMaxLength = SoftwareKeyboard.LanguageMaxLength(5);
                                    keyboardParam.invalidCharFlag = SoftwareKeyboard.InvalidChar.AtMark;
                                    keyboardParam.initialCursorPos = SoftwareKeyboard.InitialCursorPos.Last;
                                    SoftwareKeyboard.Open(keyboardParam, (resultText, errorState) => SoftwareKeyboard.InputCheck(resultText, errorState), (isSuccess, resultText) =>
                                    {
                                        BoxWork.SetTeamName(resultText, _battleTeam.Param.paramIndex);
                                        _battleTeam.SetTitle();
                                    });
                                }
                                else if (IsPushButton(UIManager.ButtonA))
                                {
                                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                                }
                                _cursorBody.SetActive(true);
                                return true;
                            }, null, 0);
                        }
                        else if (naviParam != null && _operationType == OperationType.Default && item.pokemonParam != null)
                        {
                            if (item.pokemonParam != null && item.pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
                            {
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_STATUS });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_ITEMS });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_MARKING });
                            }
                            else if (naviParam.itemType != NaviParam.ItemType.Party)
                            {
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_REGISTER });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_STATUS });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_ITEMS });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_MARKING });
                            }
                            else
                            {
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_MOVE });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_REMOVE });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_STATUS });
                            }
                            menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_CANCEL });
                            SelectPokemon(item, false);
                        }
                        break;

                    case DisplayMode.Item:
                        if (naviParam != null && _operationType == OperationType.Default && item.pokemonParam != null)
                        {
                            if (item.pokemonParam.GetItem() != 0)
                            {
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_MOVE });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_TO_BAG });
                            }
                            else
                            {
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_HAVE_ITEM });
                            }
                            menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_CANCEL });
                            SelectPokemon(item, true);
                        }
                        break;

                    case DisplayMode.Arrangement:
                        if (naviParam != null && _operationType == OperationType.Default && item.pokemonParam != null)
                        {
                            if (_param.openType == OpenType.External)
                            {
                                SelectedPokemon target = GetSelected();
                                ContextMenuID selectMenuId = ContextMenuID.BOX_SELECT;
                                if (_selected != null && _selected.Exists(x => x.TrayIndex == target.TrayIndex && x.IndexInTray == target.IndexInTray))
                                    selectMenuId = ContextMenuID.BOX_REMOVE;
                                menuItems.Add(new ContextMenuItem.Param { menuId = selectMenuId });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_STATUS });
                            }
                            else if (_param.openType != OpenType.Normal)
                            {
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_TRADE });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_STATUS });
                            }
                            else
                            {
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_MOVE });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_STATUS });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_ITEMS });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_MARKING });
                                menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_ESCAPE });
                            }
                            menuItems.Add(new ContextMenuItem.Param { menuId = ContextMenuID.BOX_CANCEL });
                            SelectPokemon(item, false);
                        }
                        break;
                }
            }

            if (menuItems.Count > 0)
                OpenContextMenu(menuItems, OnContextMenu, null, 0, 0);
        }
		private void SelectPokemon(global::Dpr.UI.BoxItem item, bool isItemMode = false) {
            item.Select(true, false);
            PokemonParam pokemonParam = item.pokemonParam;
            string messageId;
            if (isItemMode)
            {
                if (pokemonParam.GetItem() != 0)
                {
                    MessageWordSetHelper.SetItemWord(0, item.pokemonParam.GetItem(), 1);
                    messageId = "SS_box_085";
                }
                else
                {
                    messageId = "SS_box_091";
                }
            }
            else
            {
                MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
                messageId = "SS_box_043";
            }

            SetMessage(messageId);
        }
		private bool OnContextMenu(global::Dpr.UI.ContextMenuItem menuItem) {
            if (_messageWindow != null)
            {
                _messageWindow.CloseWindow();
                _messageWindow = null;
            }

            NaviParam naviParam = _navigator.userParam as NaviParam;
            BoxItem naviItem = GetNaviItem(_navigator);
            switch (menuItem.param.menuId)
            {
                case ContextMenuID.BOX_MOVE:
                case ContextMenuID.BOX_REGISTER:
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.S_ME054, null);
                    BeginIconSelect(_navigator, false);
                    break;
                case ContextMenuID.BOX_STATUS:
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    OpenStatusWindow(GetStatusParams(naviParam), GetReOpenParam(naviParam));
                    break;
                case ContextMenuID.BOX_ITEMS:
                    if (naviItem.pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
                    {
                        Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
                        if (naviItem != null)
                            naviItem.Select(false, false);
                        SetMessage("SS_box_093");
                    }
                    else if (naviItem.pokemonParam.GetItem() != 0)
                    {
                        RemoveItem(naviItem);
                    }
                    else
                    {
                        Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                        SetItem(naviParam, naviItem);
                    }
                    break;
                case ContextMenuID.BOX_MARKING:
                {
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    PokemonParam pokemonParam = naviItem.pokemonParam;
                    _cursorBody.SetActive(false);
                    _markSettingPanel.Open(pokemonParam, naviParam.itemType == NaviParam.ItemType.Tray ? _boxTray.Param.paramIndex : -1, (_navigator.userParam as NaviParam).index);
                    SetMarkingMode(true);
                    break;
                }
                case ContextMenuID.BOX_ESCAPE:
                {
                    string messageId = naviItem.pokemonParam.IsEgg(EggCheckType.BOTH_EGG) ? "SS_box_056" : "";
                    SelectedPokemon selected = GetSelected();
                    if (selected.TrayIndex >= 0 && BoxWork.IsPokeTeam(selected.TrayIndex, selected.IndexInTray))
                        messageId = "SS_box_058";

                    if (naviParam.itemType == NaviParam.ItemType.Party)
                    {
                        PokemonParam pokemonParam = naviItem.pokemonParam;
                        if (pokemonParam != null && !pokemonParam.IsEgg(EggCheckType.BOTH_EGG) && !pokemonParam.IsHpZero() && PlayerWork.playerParty.GetMemberCountEx(PokeParty.CountType.BATTLE_ENABLE) < 2)
                            messageId = "SS_box_059";
                    }

                    if (messageId != "")
                    {
                        Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
                        if (naviItem != null)
                            naviItem.Select(false, false);
                        SetMessage(messageId);
                        SetTrayNamePlate(_navigator);
                        _cursorBody.SetActive(true);
                    }
                    else
                    {
                        SetMessage("SS_box_052");
                        OpenYesNoContextMenu(item =>
                        {
                            if (naviItem != null)
                                naviItem.Select(false, false);

                            _messageWindow.CloseWindow();
                            _messageWindow = null;
                            if (item.param.menuId == ContextMenuID.BOX_YES)
                            {
                                Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                                if (naviItem.pokemonParam.GetItem() != 0)
                                    naviItem.ReturnItemInBag();

                                PokemonParam releaseParam = new PokemonParam(naviItem.pokemonParam);
                                switch (naviParam.itemType)
                                {
                                    case NaviParam.ItemType.Party:
                                        PlayerWork.playerParty.RemoveMember((uint)naviParam.index);
                                        FillPartyGap(_navigator, 1, false, () => ApplyTray(true));
                                        break;
                                    case NaviParam.ItemType.Tray:
                                    {
                                        int tray = _boxTray.Param.paramIndex;
                                        int pos = naviParam.index;
                                        BoxWork.DeleteTeam(tray, pos, true);
                                        BoxPokemonWork.ClearPokemon(tray, pos);
                                        break;
                                    }
                                }

                                MessageWordSetHelper.SetPokemonNickNameWord(0, releaseParam, true);
                                SetMessage("SS_box_055");
                                naviItem.Clear();
                                ApplyPokemonStatusAndModel(_navigator, false, true);
                                SetupKeyguide();
                            }
                            else if (IsPushButton(UIManager.ButtonA))
                            {
                                Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                            }

                            SetTrayNamePlate(_navigator);
                            _cursorBody.SetActive(true);
                            return true;
                        }, null, 1);
                    }
                    break;
                }
                case ContextMenuID.BOX_CANCEL:
                    if (IsPushButton(UIManager.ButtonA))
                        Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);

                    if (naviItem != null)
                    {
                        naviItem.Select(false, false);
                        naviItem.SetItemState(_displayMode == DisplayMode.Item);
                    }

                    SetTrayNamePlate(_navigator);
                    _cursorBody.SetActive(true);
                    break;
                case ContextMenuID.BOX_TO_BAG:
                    RemoveItem(naviItem);
                    break;
                case ContextMenuID.BOX_HAVE_ITEM:
                    if (naviItem != null)
                        naviItem.SetItemState(_displayMode == DisplayMode.Item);

                    if (naviItem.pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
                    {
                        Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
                        if (naviItem != null)
                            naviItem.Select(false, false);
                        SetMessage("SS_box_093");
                    }
                    else
                    {
                        Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                        SetItem(naviParam, naviItem);
                    }
                    break;
                case ContextMenuID.BOX_REMOVE:
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    if (_displayMode == DisplayMode.Battle)
                    {
                        if (naviItem != null)
                            naviItem.Select(false, false);
                        BeginIconSelect(_navigator, true);
                    }
                    else if (_displayMode == DisplayMode.Arrangement && _param.openType != OpenType.Normal)
                    {
                        ResetSendPokemon(GetSelected());
                    }
                    break;
                case ContextMenuID.BOX_JUMP:
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    SetSelectBoxPanel(true, _boxTray.Param.paramIndex);
                    break;
                case ContextMenuID.BOX_WALLPAPER:
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    _wallNo = BoxWork.GetWallPaper(_boxTray.Param.paramIndex);
                    _wallPaperSelector.Open(_wallNo > 0 ? _wallNo - 1 : 0);
                    SetWallPaperSelectMode(true);
                    break;
                case ContextMenuID.BOX_NAME:
                {
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    SoftwareKeyboard.Param keyboardParam = new SoftwareKeyboard.Param
                    {
                        text = BoxWork.GetTrayName(_boxTray.Param.paramIndex),
                        textMaxLength = SoftwareKeyboard.LanguageMaxLength(8),
                        invalidCharFlag = SoftwareKeyboard.InvalidChar.AtMark,
                        initialCursorPos = SoftwareKeyboard.InitialCursorPos.Last,
                    };
                    SoftwareKeyboard.Open(keyboardParam, (resultText, errorState) => SoftwareKeyboard.InputCheck(resultText, errorState), (isSuccess, resultText) =>
                    {
                        BoxWork.SetTrayName(resultText, _boxTray.Param.paramIndex);
                        _boxTray.SetTitle();
                        _cursorBody.SetActive(true);
                    });
                    break;
                }
                case ContextMenuID.BOX_TRADE:
                    SetSendPokemon(GetSelected(), true, _param.isGMS);
                    break;
                case ContextMenuID.BOX_SELECT:
                    SetSendPokemon(GetSelected(), _param.isExternalTrade, _param.isGMS);
                    break;
            }

            return true;
        }
		private bool OnTradeContextMenu(global::Dpr.UI.ContextMenuItem item) {
            if (_messageWindow != null)
            {
                _messageWindow.CloseWindow();
                _messageWindow = null;
            }

            NaviParam naviParam = _navigator.userParam as NaviParam;
            BoxItem naviItem = GetNaviItem(_navigator); // result unused (call kept @01cc5fb4)
            switch (item.param.menuId)
            {
                case ContextMenuID.BOX_STATUS:
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    OpenStatusWindow(GetStatusParams(naviParam), GetReOpenParam(naviParam));
                    break;
                case ContextMenuID.BOX_CANCEL:
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    CancelNetworkMine();
                    break;
                case ContextMenuID.BOX_TRADE:
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    _onDecide?.Invoke(this);
                    ToNextPhase();
                    break;
                case ContextMenuID.BOX_OTHER_STATUS:
                {
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    // shipped: limitType 4 (ZukanRegister) for the trade partner's status (mov w8,#4 @01cc6174)
                    PokemonStatusWindow.Param statusParams = new PokemonStatusWindow.Param();
                    statusParams.limitType = PokemonStatusWindow.Param.LimitType.ZukanRegister;
                    statusParams.pokemonParams.Add(_tradeParam.otherPokeParam);
                    statusParams.boxParams = new List<PokemonStatusWindow.Param.BoxParam>();
                    statusParams.boxParams.Add(new PokemonStatusWindow.Param.BoxParam { isPrevExchangePartner = true });
                    OpenStatusWindow(statusParams, GetReOpenParam(naviParam));
                    break;
                }
            }

            return true;
        }
		private void OpenStatusWindow(global::Dpr.UI.PokemonStatusWindow.Param statusParams, global::Dpr.UI.BoxWindow.OpenParam reopenParam) {
            SmartPoint.AssetAssistant.Sequencer.Start(FadeTransition<PokemonStatusWindow>(TransitionFadeFillColor, TransitionFadeDuration, () =>
            {
                UnityAction<UIWindow> saveOnClosed = onClosed;
                Close(_ =>
                {
                    LimitBox(true);
                    PokemonStatusWindow pokemonStatus = UIManager.Instance.CreateUIWindow<PokemonStatusWindow>(UIWindowID.POKEMON_STATUS);
                    pokemonStatus.RegisterCloseOnOpenWindow<BoxWindow>(TransitionFadeFillColor, TransitionFadeDuration, statusWindow =>
                    {
                        LimitBox(false);
                        BoxWindow boxWindow = UIManager.Instance.CreateUIWindow<BoxWindow>(UIWindowID.BOX);
                        boxWindow.onPreClose = onPreClose;
                        boxWindow.onClosed = saveOnClosed;
                        int selectIndex = (statusWindow as PokemonStatusWindow).selectIndex;
                        if (reopenParam.isSelectParty)
                        {
                            reopenParam.index = selectIndex;
                        }
                        else
                        {
                            PokemonParam pokemonParam = new PokemonParam();
                            int count = 0;
                            for (int i = 0; i < BoxWork.TRAY_POKE_MAX; i++)
                            {
                                if (!BoxPokemonWork.CheckPokemon(reopenParam.tray, i, pokemonParam, true))
                                    continue;

                                if (count == selectIndex)
                                {
                                    reopenParam.index = i;
                                    break;
                                }

                                count++;
                            }
                        }

                        switch (_param.openType)
                        {
                            case OpenType.External:
                            case OpenType.TradeNPC:
                                boxWindow.Open(reopenParam, _onSelected, pokemonStatus.instance.windowId);
                                break;
                            case OpenType.TradeNetwork:
                                boxWindow.Open(reopenParam, _tradeParam, pokemonStatus.instance.windowId);
                                break;
                            default:
                                boxWindow.Open(reopenParam, pokemonStatus.instance.windowId, _isDuckOn);
                                break;
                        }

                        boxWindow._prevWindowId = _prevWindowId;
                    });
                    pokemonStatus.Open(statusParams, instance.windowId);
                }, UIWindowID.POKEMON_STATUS);
            }));
        }
		private global::Dpr.UI.PokemonStatusWindow.Param GetStatusParams(global::Dpr.UI.BoxWindow.NaviParam naviParam) {
            return GetStatusParams(naviParam.itemType, naviParam.index);
        }
		private global::Dpr.UI.PokemonStatusWindow.Param GetStatusParams(global::Dpr.UI.BoxWindow.NaviParam.ItemType type, int index) {
            PokemonStatusWindow.Param param = new PokemonStatusWindow.Param();
            if (type == NaviParam.ItemType.Tray || _displayMode == DisplayMode.Battle)
                param.boxParams = new List<PokemonStatusWindow.Param.BoxParam>();

            param.limitType = PokemonStatusWindow.Param.LimitType.BoxSelect;
            if (_tradeParam != null && _tradeParam.tradePhase >= NetTradePhase.OtherPokeConfirm)
            {
                if (type == NaviParam.ItemType.Party)
                {
                    param.pokemonParams.Add(GetCurrentParty().Items[index].pokemonParam);
                }
                else if (type == NaviParam.ItemType.Tray)
                {
                    param.pokemonParams.Add(_boxTray.Items[index].pokemonParam);
                    param.boxParams.Add(new PokemonStatusWindow.Param.BoxParam { tray = _boxTray.Param.paramIndex, pos = index });
                }

                _tradeParam.selectIndex = index;
                param.selectIndex = 0;
                return param;
            }

            if (type == NaviParam.ItemType.Party)
            {
                BoxPartyItem[] items = System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Where(GetCurrentParty().Items, x => x.pokemonParam != null));
                int teamIndex = _battleTeam.Param.paramIndex;
                for (int i = 0; i < items.Length; i++)
                {
                    param.pokemonParams.Add(items[i].pokemonParam);
                    if (_displayMode == DisplayMode.Battle)
                    {
                        PokemonStatusWindow.Param.BoxParam boxParam = new PokemonStatusWindow.Param.BoxParam();
                        boxParam.tray = BoxWork.GetTeamPokeBoxTray(teamIndex, i);
                        boxParam.pos = BoxWork.GetTeamPokeBoxPos(teamIndex, i);
                        param.boxParams.Add(boxParam);
                    }
                }

                param.selectIndex = index;
            }
            else if (type == NaviParam.ItemType.Tray)
            {
                for (int i = 0; i < _boxTray.Items.Count; i++)
                {
                    PokemonParam pokemonParam = _boxTray.Items[i].pokemonParam;
                    if (pokemonParam == null || pokemonParam.GetMonsNo() == MonsNo.NULL)
                        continue;

                    if (index == i)
                        param.selectIndex = param.pokemonParams.Count;

                    param.pokemonParams.Add(pokemonParam);
                    param.boxParams.Add(new PokemonStatusWindow.Param.BoxParam { tray = _boxTray.Param.paramIndex, pos = i });
                }
            }

            return param;
        }
		private void BeginIconSelect(global::Dpr.UI.UINavigator navigator, bool isRemoveByTeam = false) {
            _cursorBody.SetActive(true);
            _cursor.SetFrameSprite((int)_operationType + 3);
            _cursorBody.localPosition = new Vector3(_cursorBody.localPosition.x, 42.0f, 0.0f);
            _currentTrayIndex = _trayScroll.GetParamIndex();
            BoxItem item = GetNaviItem(navigator);
            NaviParam naviParam = navigator.userParam as NaviParam;
            if (naviParam.itemType == NaviParam.ItemType.Party)
            {
                // 01cbdcb0: GetCurrentParty() (part 2, 0 callers) inlined
                _fromTray = GetCurrentParty();
                _fromTrayIndex = -1;
                _fromTeamIndex = ((BoxParty)_fromTray).Param.paramIndex;
            }
            else
            {
                _fromTray = _boxTray;
                _fromTrayIndex = _boxTray.Param.paramIndex;
                _fromTeamIndex = -1;
            }
            _fromNavigator = navigator;

            if (isRemoveByTeam)
            {
                UnregistTeam(navigator);
                ApplyTray(false);
                ApplyPokemonStatusAndModel(_navigator, false, true);
                SetupKeyguide();
                return;
            }

            _matSearchButton.SetFloat(Shader.PropertyToID("_GrayscaleAmount"), 1.0f);
            SetIconSelect(_swapIcon, navigator, true, true, null);
            _namePlate.SetActive(false);
            _currentPokeParam = item.pokemonParam;
            if (_displayMode == DisplayMode.Battle)
            {
                if (naviParam.itemType != NaviParam.ItemType.Party)
                    return;
            }
            else if (naviParam.itemType != NaviParam.ItemType.Tray)
            {
                return;
            }
            _hideIconIndexes.Add((_fromNavigator.userParam as NaviParam).index);
        }
		private bool SetSendPokemon(global::Dpr.UI.BoxWindow.SelectedPokemon target, bool isTrade = false, bool isGMS = false) {
            BoxItem item = GetNaviItem(_navigator);
            item.Select(false, false);
            if (item.pokemonParam == null)
                return false;

            // 01cbe238: UnionWork.GetBoxState() / SetBoxState() inlined behind indirect flag slots
            if (_param.openType == OpenType.TradeNetwork && UnionWork.GetBoxState() == UnionWork.BoxState.CANCEL_SELECT)
                UnionWork.SetBoxState(UnionWork.BoxState.NONE);

            string messageID = "";
            if (!_param.isEnableEgg && item.pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
                messageID = isGMS ? "SS_box_195" : "SS_box_211";

            PokemonParam pokemonParam = item.pokemonParam;
            if (_param.selectNgPokeNos != null)
            {
                int monsNo = (int)pokemonParam.GetMonsNo();
                for (int i = 0; i < _param.selectNgPokeNos.Length; i++)
                {
                    if (monsNo == _param.selectNgPokeNos[i])
                    {
                        messageID = "SS_box_580";
                        break;
                    }
                }
            }

            if (!_param.isEnableDying && item.pokemonParam.IsHpZero() && !item.pokemonParam.IsEgg(EggCheckType.ONLY_ILLEGAL_EGG))
                messageID = "SS_box_216";

            if (!_param.isEnableTeam && target.TrayIndex >= 0 && BoxWork.IsPokeTeam(target.TrayIndex, target.IndexInTray))
                messageID = isGMS ? "SS_box_196" : "SS_box_212";

            if (!_param.isEnableParty && target.TrayIndex < 0)
                messageID = "SS_box_214";

            if (isTrade && target.TrayIndex < 0 && !item.pokemonParam.IsEgg(EggCheckType.BOTH_EGG) && !PlayerWork.playerParty.CanTradeMember((uint)target.IndexInTray))
                messageID = "SS_box_059";

            if (item.pokemonParam.GetDprIllegalFlag())
            {
                if (isTrade)
                    messageID = "SS_box_182";
                else if (_param.isDisableDuplicate)
                    messageID = "SS_box_589";
            }

            if (isTrade && item.pokemonParam.IsEgg(EggCheckType.ONLY_ILLEGAL_EGG))
                messageID = "SS_box_188";

            if (messageID != "")
            {
                Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
                SetMessage(messageID, true, null, null, false);
                SetTrayNamePlate(_navigator);
                _cursorBody.SetActive(true);
                return false;
            }

            Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
            item.SetExternalSelectIcon(true);
            _selected.Add(target);
            SetSelectCountPlate();
            if (_selected.Count != _param.selectCount)
            {
                SetTrayNamePlate(_navigator);
                _cursorBody.SetActive(true);
                return true;
            }

            // 01cbe718: ReturnPairPokemon() inlined (init flag 0xdfa)
            if (isTrade && target.TrayIndex < 0 && IsHitSelectType(item.pokemonParam, _param))
                ReturnPairPokemon(item.pokemonParam);

            if (_param.openType == OpenType.TradeNetwork)
            {
                _tradeParam.selectIndex = target.IndexInTray;
                _onSelected?.Invoke(this, _selected.ToArray());
                // 01cbe808: ToNextPhase() inlined
                ToNextPhase();
                return true;
            }

            _onSelected?.Invoke(this, _selected.ToArray());
            Close(onClosed, _prevWindowId);
            return true;
        }
		private void ResetSendPokemon(global::Dpr.UI.BoxWindow.SelectedPokemon target) {
            BoxItem item = GetNaviItem(_navigator);
            if (item.pokemonParam != null)
            {
                if (item != null)
                {
                    item.Select(false, false);
                    item.SetExternalSelectIcon(false);
                }

                for (int i = _selected.Count - 1; i >= 0; i--)
                {
                    if (_selected[i].TrayIndex == target.TrayIndex && _selected[i].IndexInTray == target.IndexInTray)
                    {
                        _selected.RemoveAt(i);
                        SetSelectCountPlate();
                        break;
                    }
                }
            }

            SetTrayNamePlate(_navigator);
            _cursorBody.SetActive(true);
        }
