		private void RemoveItem(global::Dpr.UI.BoxItem naviItem) {
            ushort itemNo = naviItem.pokemonParam.GetItem();
            if (ItemWork.IsAddItem(itemNo, 1))
            {
                MessageWordSetHelper.SetItemWord(0, itemNo, 1);
                SetMessage("SS_box_090");
                OpenYesNoContextMenu(item =>
                {
                    _messageWindow.CloseWindow();
                    _messageWindow = null;
                    if (item.param.menuId == ContextMenuID.BOX_YES)
                    {
                        Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                        naviItem.ReturnItemInBag();
                        NaviParam naviParam = _navigator.userParam as NaviParam;
                        int trayIndex = naviParam.itemType == NaviParam.ItemType.Tray ? _boxTray.Param.paramIndex : -1;
                        int index = naviParam.index;
                        UpdatePokemonPaaram(trayIndex, index, naviItem.pokemonParam);
                        ApplyTray(trayIndex < 0);
                        if (trayIndex >= 0)
                            ApplyBoxList(trayIndex);

                        bool isFormChange = SetFormChangeByItem(naviItem.pokemonParam);
                        if (isFormChange)
                            UpdatePokemonPaaram(trayIndex, index, naviItem.pokemonParam);

                        MessageWordSetHelper.SetItemWord(0, itemNo, 1);
                        SetMessage("SS_box_088", true, () => formChangeEffect(isFormChange, naviItem));
                    }
                    else if (IsPushButton(UIManager.ButtonA))
                    {
                        Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    }

                    if (naviItem != null)
                    {
                        naviItem.Select(false, false);
                        naviItem.SetItemState(_displayMode == DisplayMode.Item);
                    }

                    SetTrayNamePlate(_navigator);
                    _cursorBody.SetActive(true);
                    return true;
                }, null, 0);
            }
            else
            {
                Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
                SetMessage("SS_box_089");
                if (naviItem != null)
                {
                    naviItem.Select(false, false);
                    naviItem.SetItemState(_displayMode == DisplayMode.Item);
                }

                SetTrayNamePlate(_navigator);
                _cursorBody.SetActive(true);
            }
        }
		private void formChangeEffect(bool isFormChange, global::Dpr.UI.BoxItem naviItem) {
            PlayFormChangeeffect(isFormChange, naviItem.pokemonParam, naviItem.GetSwapRoot(), true, () =>
            {
                naviItem.Setup();
                ApplyPokemonStatusAndModel(_navigator, false, true);
                if (_displayMode == DisplayMode.Battle)
                    ApplyTray(true);
            }, null);
        }
		private void CancelNetworkMine() {
            _onCancelSelect?.Invoke(this);
            ClearTradeSelected();
        }
		private void CancelNetworkTrade() {
            SetMessage("SS_box_180", true);
            OpenYesNoContextMenu(item =>
            {
                if (_messageWindow != null)
                    _messageWindow.CloseWindow();

                _messageWindow = null;
                if (item.param.menuId == ContextMenuID.BOX_YES)
                {
                    Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
                    if (_tradeParam.tradePhase == NetTradePhase.PlayerSelecting)
                        SetMessage("SS_box_178", true, () => Close(onClosed, _prevWindowId));
                    else
                        CancelNetworkMine(); // 01cd00b4: inlined, its flag 0xde4
                }
                else
                {
                    if (IsPushButton(UIManager.ButtonA))
                        Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);

                    if (_tradeParam.tradePhase >= NetTradePhase.OtherPokeConfirm)
                    {
                        SetMessage("SS_box_187", true);
                        OpenTradeConfirmContextMenu(OnTradeContextMenu);
                    }
                }

                if (_param.openType != OpenType.TradeNetwork || _tradeParam.tradePhase < NetTradePhase.WaitSend)
                {
                    SetTrayNamePlate(_navigator);
                    _cursorBody.SetActive(true);
                }
                return true;
            }, null, 1);
        }
		public void ClearTradeSelected() {
            // 01cbc78c: SetModelTradePanel(false) inlined (flag 0xdc6)
            SetModelTradePanel(false);
            if (_selected == null || _selected.Count < 1)
                return;

            if (_selected[0].TrayIndex < 0)
                _partyNormal.Items[_selected[0].IndexInTray].SetExternalSelectIcon(false);
            else if (_selected[0].TrayIndex == _currentTrayIndex)
                _boxTray.Items[_selected[0].IndexInTray].SetExternalSelectIcon(false);

            _selected.Clear();
        }
