		private void SetMessage(string msgFile, string messageID, bool isCloseEnable = true, global::System.Action onClose = null, global::System.Action onShow = null, bool isNetTrade = false) {
            MsgWindowParam param;
            if (msgFile != null)
            {
                param = new MsgWindowParam();
                param.useMsgFile = MessageManager.Instance.GetMsgFile(msgFile);
            }
            else
            {
                if (_messageParam == null)
                {
                    _messageParam = new MsgWindowParam();
                    _messageParam.useMsgFile = MessageManager.Instance.GetMsgFile(BoxMsgFileName);
                }

                param = _messageParam;
            }

            param.onFinishedCloseWindow = () =>
            {
                _messageWindow = null;
                onClose?.Invoke();
            };
            param.onFinishedShowAllMessage = () => onShow?.Invoke();
            param.labelName = messageID;
            param.inputCloseEnabled = isCloseEnable;
            param.isNetwork = isNetTrade;
            param.showLoadingIcon = isNetTrade;
            _messageWindow = MsgWindowManager.OpenMsg(param);
            _currentMsgID = messageID;
