		private void BeginRangeSwap() {
            _input.inputEnabled = false;
            NaviParam fromParam = _fromNavigator.userParam as NaviParam;
            NaviParam toParam = _navigator.userParam as NaviParam;
            if (toParam.itemType == NaviParam.ItemType.Party)
            {
                if (fromParam.itemType == NaviParam.ItemType.Tray)
                {
                    if (_displayMode == DisplayMode.Battle)
                        MoveRangeTeamByTray();
                    else
                        MoveRangePartyByTray();
                }
                else if (fromParam.itemType == NaviParam.ItemType.Party)
                {
                    if (_displayMode == DisplayMode.Battle)
                        MoveRangeTeamByTeam();
                    else
                        MoveRangePartyByParty();
                }
            }
            else if (toParam.itemType == NaviParam.ItemType.Tray)
            {
                if (fromParam.itemType == NaviParam.ItemType.Party)
                {
                    if (_displayMode == DisplayMode.Battle)
                        RangeUnregistTeam();
                    else
                        MoveRangeTrayByParty();
                }
                else if (fromParam.itemType == NaviParam.ItemType.Tray)
                {
                    if (_displayMode == DisplayMode.Battle)
                    {
                        Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
                        _input.inputEnabled = true;
                    }
                    else
                    {
                        BeginRangeTrayByTray();
                    }
                }
            }
        }
		private void MoveRangePartyByParty() {
            BoxParty party = GetCurrentParty();
            int fromBeginIndex = (_fromNavigators[0].userParam as NaviParam).index;
            int toBeginIndex = (_toNavigators[0].userParam as NaviParam).index;
            int memberCount = (int)PlayerWork.playerParty.GetMemberCount();
            int moveCount = _fromNavigators.Count;
            int packIndex = fromBeginIndex + moveCount;
            List<UINavigator> setNavigators = new List<UINavigator>(moveCount);
            bool isChange = toBeginIndex >= memberCount;
            if (isChange)
            {
                int pairIndex = GetPairPokemonIndex();
                if (pairIndex >= 0)
                    ReturnPairPokemon(GetPartyPokemonParam(pairIndex));

                PokemonParam[] moveParams = new PokemonParam[moveCount];
                int[] capsuleIds = new int[moveCount];
                int newPairIndex = -1;
                for (int i = fromBeginIndex; i < fromBeginIndex + moveCount; i++)
                {
                    PokemonParam pokemonParam = GetPartyPokemonParam(i);
                    moveParams[i - fromBeginIndex] = new PokemonParam(pokemonParam);
                    if (pairIndex == i)
                        newPairIndex = pairIndex - fromBeginIndex;

                    capsuleIds[i - fromBeginIndex] = Dpr.BallDeco.BallDecoWork.GetAttachCapsuleId(pokemonParam.GetID(), pokemonParam.GetPersonalRnd(), -1, i);
                }

                for (int i = packIndex; i < memberCount; i++)
                {
                    PlayerWork.playerParty.ExchangePosition((byte)(i - moveCount), (byte)i);
                    if (pairIndex == i)
                        SetPairPokemon(GetPartyPokemonParam(pairIndex - moveCount));
                }

                int setBeginIndex = memberCount - moveCount;
                for (int i = setBeginIndex; i < memberCount; i++)
                {
                    int moveIndex = i - setBeginIndex;
                    PokemonParam pokemonParam = moveParams[moveIndex];
                    PlayerWork.playerParty.ReplaceMember((byte)i, pokemonParam);
                    setNavigators.Add(party.Items[i].navigator);
                    if (newPairIndex == moveIndex)
                        SetPairPokemon(GetPartyPokemonParam(i));

                    if (capsuleIds[moveIndex] >= 0)
                        Dpr.BallDeco.BallDecoWork.SetAttachCapsule(capsuleIds[moveIndex], pokemonParam.GetID(), pokemonParam.GetPersonalRnd(), -1, i);
                }
            }

            Vector3[] toPositions = new Vector3[moveCount];
            for (int i = 0; i < moveCount; i++)
                toPositions[i] = party.Items[toBeginIndex + i].GetSwapRoot().transform.position;

            _twSequence = SetIconMoveSequence(moveCount, _swapIcons.ToArray(), toPositions, () =>
            {
                if (isChange)
                {
                    for (int i = 0; i < memberCount - packIndex; i++)
                    {
                        setNavigators.Add(party.Items[fromBeginIndex + i].navigator);
                        PokemonIcon icon = GetNaviItem(party.Items[fromBeginIndex + moveCount + i].navigator).GetSwapRoot();
                        SetRangeSwapIcon(moveCount + i, icon);
                        icon.SetActive(false);
                    }

                    RestoreRangeSelect(true, false, true, setNavigators, null);
                }
                else
                {
                    RestoreRangeSelect(true, false, true, _fromNavigators, null);
                }
            });
        }
		private void MoveRangeTeamByTeam() {
            BoxParty toTeam = GetCurrentParty();
            // shipped @01cc774c: _fromNavigators[0] is bounds-checked and the element never used
            UINavigator firstFromNavigator = _fromNavigators[0];
            int fromTeamIndex = _fromTeamIndex;
            int toTeamIndex = GetCurrentParty().Param.paramIndex;
            int toFirstIndex = (_toNavigators[0].userParam as NaviParam).index;
            int memberCount = BoxWork.GetTeamPokeCount(toTeamIndex);
            int moveCount = _fromNavigators.Count;
            if (toTeamIndex == fromTeamIndex && toFirstIndex == (_fromNavigators[0].userParam as NaviParam).index)
            {
                RestoreRangeSelect(false, true, true, null, null);
                return;
            }

            (int, int)[] beforePositions = new (int, int)[memberCount];
            for (int i = 0; i < memberCount; i++)
            {
                beforePositions[i].Item1 = BoxWork.GetTeamPokeBoxTray(toTeamIndex, i);
                beforePositions[i].Item2 = BoxWork.GetTeamPokeBoxPos(toTeamIndex, i);
            }

            (int, int)[] fromTrayPositions = new (int, int)[moveCount];
            for (int i = 0; i < moveCount; i++)
            {
                int fromIndex = (_fromNavigators[i].userParam as NaviParam).index;
                fromTrayPositions[i].Item1 = BoxWork.GetTeamPokeBoxTray(fromTeamIndex, fromIndex);
                fromTrayPositions[i].Item2 = BoxWork.GetTeamPokeBoxPos(fromTeamIndex, fromIndex);
            }

            for (int i = 0; i < moveCount; i++)
                BoxWork.SetTeamPokePos(toTeamIndex, (_toNavigators[i].userParam as NaviParam).index, fromTrayPositions[i].Item1, fromTrayPositions[i].Item2);

            BoxWork.PackTeam(toTeamIndex);

            Vector3[] toPositions = new Vector3[moveCount * 2];
            for (int i = 0; i < moveCount; i++)
            {
                BoxPartyItem item = toTeam.Items[toFirstIndex + i];
                toPositions[i] = item.GetSwapRoot().transform.position;
                item.SetIconDefault(false);
                for (int j = 0; j < memberCount; j++)
                {
                    if (fromTrayPositions[i] == beforePositions[j])
                        toTeam.Items[j].SetIconDefault(false);
                }
            }

            _twSequence = SetIconMoveSequence(moveCount, _swapIcons.ToArray(), toPositions, () =>
            {
                memberCount = BoxWork.GetTeamPokeCount(toTeamIndex);
                List<UINavigator> toNavigators = new List<UINavigator>(6);
                List<int> hitIndexes = new List<int>();
                for (int i = 0; i < memberCount; i++)
                {
                    int tray = BoxWork.GetTeamPokeBoxTray(toTeamIndex, i);
                    int pos = BoxWork.GetTeamPokeBoxPos(toTeamIndex, i);
                    for (int j = 0; j < moveCount; j++)
                    {
                        if (fromTrayPositions[j] == (tray, pos))
                        {
                            hitIndexes.Add(i);
                            toNavigators.Add(toTeam.Items[i].navigator);
                            break;
                        }
                    }
                }

                for (int i = 0; i < memberCount; i++)
                {
                    int tray = BoxWork.GetTeamPokeBoxTray(toTeamIndex, i);
                    int pos = BoxWork.GetTeamPokeBoxPos(toTeamIndex, i);
                    for (int j = 0; j < beforePositions.Length; j++)
                    {
                        if (!hitIndexes.Contains(i) && j != i && beforePositions[j] == (tray, pos))
                        {
                            toNavigators.Add(toTeam.Items[i].navigator);
                            BoxPartyItem item = GetNaviItem(toTeam.Items[j].navigator) as BoxPartyItem;
                            PokemonIcon icon = item.GetSwapRoot();
                            SetRangeSwapIcon(toNavigators.Count - 1, icon);
                            item.SetIconDefault(false);
                        }
                    }
                }

                RestoreRangeSelect(true, false, true, toNavigators, null);
                _hideIconIndexes.Clear();
                ApplyTray(false);
            });
        }
		private void BeginRangeTrayByTray() {
            for (int i = 0; i < _toNavigators.Count; i++)
            {
                if (!_existSwapIndexes.Contains(i))
                    continue;

                NaviParam fromNaviParam = _fromNavigators[i].userParam as NaviParam;
                if (fromNaviParam == null || _toNavigators[i].userParam == null)
                    continue;

                if (!BoxPokemonWork.CheckPokemon(_fromTrayIndex, fromNaviParam.index, true))
                    continue;

                int toTrayIndex = _boxTray.Param.paramIndex;
                if (_boxTray.Items[(_toNavigators[i].userParam as NaviParam).index].pokemonParam == null)
                {
                    MoveTrayByTray(_fromNavigators[i], _toNavigators[i]);
                    continue;
                }

                if (_fromTrayIndex != toTrayIndex)
                    continue;

                for (int j = 0; j < _fromNavigators.Count; j++)
                {
                    if (_fromNavigators[j] == _toNavigators[i])
                    {
                        _fromNavigators[j] = _fromNavigators[i];
                        break;
                    }
                }

                SwapTrayByTray(_fromNavigators[i], _toNavigators[i]);
            }

            RestoreRangeSelect(true, false, true, null, null);
        }
		private void MoveRangePartyByTray() {
            int fromTrayIndex = _fromTrayIndex;
            BoxParty party = _partyNormal;
            int toBeginIndex = (_toNavigators[0].userParam as NaviParam).index;
            int moveCount = _fromNavigators.Count;
            List<UINavigator> setNavigators = new List<UINavigator>(moveCount);
            for (int i = 0; i < moveCount; i++)
            {
                setNavigators.Add(null);
                int fromIndex = (_fromNavigators[i].userParam as NaviParam).index;
                PokemonParam pokemonParam = BoxPokemonWork.GetPokemon(fromTrayIndex, fromIndex);
                if (pokemonParam.IsNull())
                    continue;

                int capsuleId = Dpr.BallDeco.BallDecoWork.GetAttachCapsuleId(pokemonParam.GetID(), pokemonParam.GetPersonalRnd(), fromTrayIndex, fromIndex);
                if (pokemonParam.GetMonsNo() == MonsNo.SHEIMI && pokemonParam.GetFormNo() == 1)
                    _effectIndexes.Add((int)PlayerWork.playerParty.GetMemberCount());

                PlayerWork.playerParty.AddMember(new PokemonParam(pokemonParam));
                BoxPokemonWork.ClearPokemon(fromTrayIndex, fromIndex);
                BoxWork.DeleteTeam(fromTrayIndex, fromIndex, true);
                int partyIndex = (int)PlayerWork.playerParty.GetMemberCount() - 1;
                setNavigators[i] = party.Items[partyIndex].navigator;
                if (capsuleId >= 0)
                    Dpr.BallDeco.BallDecoWork.SetAttachCapsule(capsuleId, pokemonParam.GetID(), pokemonParam.GetPersonalRnd(), -1, partyIndex);
            }

            Vector3[] toPositions = new Vector3[moveCount];
            for (int i = 0; i < moveCount; i++)
                toPositions[i] = party.Items[toBeginIndex + i].GetSwapRoot().transform.position;

            _twSequence = SetIconMoveSequence(moveCount, _swapIcons.ToArray(), toPositions, () =>
            {
                RestoreRangeSelect(true, false, true, setNavigators, null);
                _hideIconIndexes.Clear();
                ApplyTray(false);
            });
        }
		private void MoveRangeTeamByTray() {
            int fromTrayIndex = _fromTrayIndex;
            BoxParty toTeam = _battleTeam;
            int teamIndex = toTeam.Param.paramIndex;
            int toBeginIndex = (_toNavigators[0].userParam as NaviParam).index;
            int moveCount = _fromNavigators.Count;
            int memberCount = BoxWork.GetTeamPokeCount(teamIndex);
            List<int> targetIndexes = new List<int>(moveCount);
            List<UINavigator> setNavigators = new List<UINavigator>(6);
            (int, int)[] beforePositions = new (int, int)[memberCount];
            for (int i = 0; i < memberCount; i++)
            {
                beforePositions[i].Item1 = BoxWork.GetTeamPokeBoxTray(teamIndex, i);
                beforePositions[i].Item2 = BoxWork.GetTeamPokeBoxPos(teamIndex, i);
            }

            for (int i = 0; i < moveCount; i++)
            {
                setNavigators.Add(null);
                targetIndexes.Add(-1);
                int fromIndex = (_fromNavigators[i].userParam as NaviParam).index;
                PokemonParam pokemonParam = BoxPokemonWork.GetPokemon(fromTrayIndex, fromIndex);
                if (pokemonParam.IsNull())
                    continue;

                if (pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
                {
                    SetMessage("SS_box_103");
                    RestoreRangeSelect(false, true, true, null, null);
                    return;
                }

                targetIndexes[i] = fromIndex;
            }

            for (int i = 0; i < moveCount; i++)
            {
                int targetIndex = targetIndexes[i];
                if (targetIndex < 0)
                    continue;

                BoxWork.SetTeamPokePos(teamIndex, toBeginIndex + i, fromTrayIndex, targetIndex);
                BoxWork.PackTeam(teamIndex);
                // shipped @01cc8878: the new team position is looked up and dropped
                int teamPos = BoxWork.GetPokeTeamPos(fromTrayIndex, targetIndex, teamIndex);
            }

            Vector3[] toPositions = new Vector3[moveCount * 2];
            for (int i = 0; i < moveCount; i++)
            {
                int toIndex = toBeginIndex + i;
                BoxPartyItem item = toTeam.Items[toIndex];
                toPositions[i] = item.GetSwapRoot().transform.position;
                if (targetIndexes[i] >= 0 && toIndex < memberCount)
                {
                    if (BoxWork.GetPokeTeamPos(beforePositions[toIndex].Item1, beforePositions[toIndex].Item2, teamIndex) == BoxWork.TEAM_POKE_MAX)
                        item.SetIconDefault(false);
                }

                for (int j = 0; j < memberCount; j++)
                {
                    if (fromTrayIndex == beforePositions[j].Item1 && (_fromNavigators[i].userParam as NaviParam).index == beforePositions[j].Item2)
                        toTeam.Items[j].SetIconDefault(false);
                }
            }

            _twSequence = SetIconMoveSequence(moveCount, _swapIcons.ToArray(), toPositions, () =>
            {
                memberCount = BoxWork.GetTeamPokeCount(teamIndex);
                List<int> hitIndexes = new List<int>();
                for (int i = 0; i < memberCount; i++)
                {
                    int tray = BoxWork.GetTeamPokeBoxTray(teamIndex, i);
                    int pos = BoxWork.GetTeamPokeBoxPos(teamIndex, i);
                    for (int j = 0; j < moveCount; j++)
                    {
                        if (tray == fromTrayIndex && pos == targetIndexes[j])
                        {
                            hitIndexes.Add(i);
                            setNavigators[j] = toTeam.Items[i].navigator;
                            break;
                        }
                    }
                }

                for (int i = 0; i < memberCount; i++)
                {
                    int tray = BoxWork.GetTeamPokeBoxTray(teamIndex, i);
                    int pos = BoxWork.GetTeamPokeBoxPos(teamIndex, i);
                    for (int j = 0; j < beforePositions.Length; j++)
                    {
                        if (!hitIndexes.Contains(i) && j != i && beforePositions[j] == (tray, pos))
                        {
                            setNavigators.Add(toTeam.Items[i].navigator);
                            BoxPartyItem item = GetNaviItem(toTeam.Items[j].navigator) as BoxPartyItem;
                            PokemonIcon icon = item.GetSwapRoot();
                            SetRangeSwapIcon(setNavigators.Count - 1, icon);
                            item.SetIconDefault(false);
                        }
                    }
                }

                RestoreRangeSelect(true, false, true, setNavigators, null);
                _hideIconIndexes.Clear();
                ApplyTray(false);
            });
        }
		private void MoveRangeTrayByParty() {
            int startIndex = (_fromNavigators[0].userParam as NaviParam).index;
            int toTrayIndex = _boxTray.Param.paramIndex;
            uint memberCount = PlayerWork.playerParty.GetMemberCount();
            int packCount = _fromNavigators.Count;
            var moveParams = new List<PokemonParam>();
            var capsuleIds = new List<int>();
            int pairIndex = -1;
            if (memberCount > 0)
            {
                int battleCount = 0;
                int moveBattleCount = 0;
                for (int i = 0; i < memberCount; i++)
                {
                    PokemonParam pokemonParam = GetPartyPokemonParam(i);
                    if (FieldManager.fwMng != null && FieldManager.fwMng.PartnerPokeParam == pokemonParam)
                        pairIndex = i;

                    // 01cc1028: CanBattlePokemon() (part 2, 0 callers) inlined
                    bool canBattle = CanBattlePokemon(pokemonParam);
                    if (canBattle)
                        battleCount++;

                    if (i >= startIndex && i < startIndex + packCount)
                    {
                        moveParams.Add(pokemonParam != null ? new PokemonParam(pokemonParam) : null);
                        if (canBattle)
                            moveBattleCount++;
                        capsuleIds.Add(Dpr.BallDeco.BallDecoWork.GetAttachCapsuleId(pokemonParam.GetID(), pokemonParam.GetPersonalRnd(), -1, i));
                    }
                }

                if (battleCount > 0 && battleCount == moveBattleCount)
                {
                    SetMessage("SS_box_059", true, null, null, false);
                    RestoreRangeSelect(false, true, true, null, null);
                    return;
                }
            }

            // 01cc11c4: ReturnPairPokemon() inlined (init flag 0xdfa)
            if (pairIndex >= startIndex)
                ReturnPairPokemon(GetPartyPokemonParam(pairIndex));

            for (int i = startIndex; i < packCount; i++)
            {
                int fromIndex = packCount + i;
                if (fromIndex >= (int)memberCount - 1)
                    break;

                PlayerWork.playerParty.ReplaceMember((byte)i, GetPartyPokemonParam(fromIndex));
                Dpr.BallDeco.BallDecoWork.MoveCapsuleExtraData(-1, i, -1, fromIndex);
            }

            uint restCount = PlayerWork.playerParty.GetMemberCount();
            int restStart = startIndex + packCount;
            var restParams = new PokemonParam[restCount - restStart];
            var restCapsuleIds = new int[restParams.Length];
            for (int i = 0; restStart + i < restCount; i++)
            {
                int index = restStart + i;
                restParams[i] = PlayerWork.playerParty.GetMemberPointer((uint)index);
                restCapsuleIds[i] = Dpr.BallDeco.BallDecoWork.GetAttachCapsuleId(restParams[i].GetID(), restParams[i].GetPersonalRnd(), -1, index);
            }

            for (int i = 0; i < packCount; i++)
            {
                if (PlayerWork.playerParty.GetMemberCount() <= startIndex)
                    break;
                PlayerWork.playerParty.RemoveMember((byte)startIndex);
            }

            if (pairIndex >= restStart && pairIndex - packCount < PlayerWork.playerParty.GetMemberCount())
                SetPairPokemon(PlayerWork.playerParty.GetMemberPointerConst((uint)(pairIndex - packCount)));

            for (int i = 0; i < restCapsuleIds.Length; i++)
            {
                if (restCapsuleIds[i] < 0)
                    continue;

                int memberIndex = (int)PlayerWork.playerParty.GetMemberIndex(restParams[i]);
                Dpr.BallDeco.BallDecoWork.SetAttachCapsule(restCapsuleIds[i], restParams[i].GetID(), restParams[i].GetPersonalRnd(), -1, memberIndex);
            }

            for (int i = 0; i < moveParams.Count; i++)
            {
                if (moveParams[i] == null)
                    continue;

                BoxPokemonWork.PutPokemon(moveParams[i], toTrayIndex, (_toNavigators[i].userParam as NaviParam).index);
                if (capsuleIds[i] >= 0)
                    Dpr.BallDeco.BallDecoWork.SetAttachCapsule(capsuleIds[i], moveParams[i].GetID(), moveParams[i].GetPersonalRnd(), toTrayIndex, (_toNavigators[i].userParam as NaviParam).index);
            }

            RestoreRangeSelect(true, false, true, null, null);
            _hideIconIndexes.Clear();
            FillPartyGap(_fromNavigators[0], packCount, false, () => ApplyTray(true));
        }
		private void RangeUnregistTeam() {
            int fromIndex = (_fromNavigators[0].userParam as NaviParam).index;
            BoxParty party = GetCurrentParty();
            int teamCount = BoxWork.GetTeamPokeCount(_fromTeamIndex);
            int count = _fromNavigators.Count;
            for (int i = 0; i < count; i++)
                BoxWork.DeletePackTeam(_fromTeamIndex, fromIndex);

            if (_fromTeamIndex == _battleTeam.Param.paramIndex)
            {
                for (int i = fromIndex; i < fromIndex + count; i++)
                    (GetNaviItem(party.Items[i].navigator) as BoxPartyItem).SetIconDefault(false);
            }

            _hideIconIndexes.Clear();
            RestoreRangeSelect(true, false, false, null, null);
            FillPartyGap(_fromNavigators[0], count, false, () => ApplyTray(true));
        }
		private void BeginSwap() {
            _input.inputEnabled = false;
            NaviParam.ItemType fromType = (_fromNavigator.userParam as NaviParam).itemType;
            NaviParam.ItemType toType = (_navigator.userParam as NaviParam).itemType;
            if (_displayMode == DisplayMode.Item)
            {
                int fromTrayIndex = _fromTrayIndex;
                int toTrayIndex = _boxTray.Param.paramIndex;
                BoxItem toItem = GetNaviItem(_navigator);
                if (toItem.pokemonParam != null)
                {
                    if (((fromType == NaviParam.ItemType.Party && toType == NaviParam.ItemType.Party) || fromTrayIndex == toTrayIndex) && _navigator == _fromNavigator)
                    {
                        RestoreSelect(false, true, true, null, null);
                        return;
                    }

                    if (toItem.pokemonParam.GetItem() == 0)
                        MoveItem(_fromNavigator, _navigator);
                    else
                        SwapItem(_fromNavigator, _navigator);
                    return;
                }
            }
            else if (fromType == NaviParam.ItemType.Party || toType == NaviParam.ItemType.Party)
            {
                if (fromType == NaviParam.ItemType.Party && toType == NaviParam.ItemType.Party)
                {
                    if (_displayMode == DisplayMode.Battle)
                        BeginTeamPartyByParty(_fromNavigator, _navigator);
                    else
                        BeginPartyByParty(_fromNavigator, _navigator);
                }
                else if (fromType != NaviParam.ItemType.Party && toType == NaviParam.ItemType.Party)
                {
                    if (_displayMode == DisplayMode.Battle)
                        BeginRegistTeamByTray(_fromNavigator, _navigator);
                    else if (GetNaviItem(_navigator).pokemonParam == null)
                        MoveLastPartyByTray(_fromNavigator, _navigator);
                    else
                        SwapPartyByTray(_fromNavigator, _navigator);
                }
                else if (fromType == NaviParam.ItemType.Party && toType != NaviParam.ItemType.Party)
                {
                    if (_displayMode == DisplayMode.Battle)
                        UnregistTeam(_fromNavigator);
                    else if (GetNaviItem(_navigator).pokemonParam == null)
                        MoveTrayByParty(_fromNavigator, _navigator);
                    else
                        SwapTrayByParty(_fromNavigator, _navigator);
                }
                return;
            }
            else if (_displayMode != DisplayMode.Battle)
            {
                BeginTrayByTray(_navigator);
                return;
            }

            Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
            _input.inputEnabled = true;
        }
		private void BeginTrayByTray(global::Dpr.UI.UINavigator toNavigator) {
            BoxItem naviItem = GetNaviItem(toNavigator);
            if (_fromTrayIndex == _boxTray.Param.paramIndex && toNavigator == _fromNavigator)
            {
                RestoreSelect(false, true, true, null, null);
                return;
            }

            if (naviItem.pokemonParam != null)
                SwapTrayByTray(_fromNavigator, _navigator);
            else
                MoveTrayByTray(_fromNavigator, _navigator);
        }
		private void MoveTrayByTray(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromTrayIndex = _fromTrayIndex;
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            int toTrayIndex = _boxTray.Param.paramIndex;
            int toIndex = (toNavigator.userParam as NaviParam).index;
            BoxPokemonWork.MovePokemon(fromTrayIndex, fromIndex, toTrayIndex, toIndex, 1, 1, new PokemonParam());
            BoxWork.ChangePokemon(fromTrayIndex, fromIndex, toTrayIndex, toIndex);
            Dpr.BallDeco.BallDecoWork.MoveCapsuleExtraData(fromTrayIndex, fromIndex, toTrayIndex, toIndex);
            if (!IsRangeSwap())
                RestoreSelect(true, true, true, null, null);
        }
		private void SwapTrayByTray(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            int toTrayIndex = _boxTray.Param.paramIndex;
            int toIndex = (toNavigator.userParam as NaviParam).index;
            int fromTrayIndex = _fromTrayIndex;
            BoxPokemonWork.SwapPokemon(fromTrayIndex, fromIndex, toTrayIndex, toIndex);
            BoxWork.ChangePokemon(fromTrayIndex, fromIndex, toTrayIndex, toIndex);
            Dpr.BallDeco.BallDecoWork.SwapCapsuleExtraData(fromTrayIndex, fromIndex, toTrayIndex, toIndex);
            if (IsRangeSwap())
                return;

            RestoreSelect(true, true, true, null, null);
            if (fromTrayIndex == toTrayIndex)
                SetTrayIconSwap(_swapIcons[1], toNavigator, fromNavigator, null);
        }
		private void BeginPartyByParty(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int teamIndex = GetCurrentParty().Param.paramIndex;
            BoxItem naviItem = GetNaviItem(toNavigator);
            if (_fromTeamIndex == teamIndex && toNavigator == fromNavigator)
            {
                RestoreSelect(false, true, true, null, null);
                return;
            }

            if (naviItem.pokemonParam != null)
                SwapPartyByParty(fromNavigator, toNavigator);
            else
                MoveLastPartyByParty(fromNavigator, toNavigator);
        }
		private void MoveLastPartyByParty(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            int memberCount = _displayMode == DisplayMode.Battle ? BoxWork.GetTeamPokeCount(_battleTeam.Param.paramIndex) : (int)PlayerWork.playerParty.GetMemberCount();
            PokemonParam fromParam = GetPartyPokemonParam(fromIndex);
            PokemonParam copyParam = new PokemonParam(fromParam);
            int pairIndex = GetPairPokemonIndex();
            if (pairIndex != -1)
                ReturnPairPokemon(GetPartyPokemonParam(pairIndex));

            int capsuleId = Dpr.BallDeco.BallDecoWork.GetAttachCapsuleId(fromParam.GetID(), fromParam.GetPersonalRnd(), -1, fromIndex);
            int lastIndex = memberCount - 1;
            int newPairIndex = -1;
            for (int i = fromIndex; i < lastIndex; i++)
            {
                PokemonParam next = GetPartyPokemonParam(i + 1);
                PlayerWork.playerParty.ReplaceMember((byte)i, next);
                if (pairIndex == i + 1)
                    newPairIndex = i;

                Dpr.BallDeco.BallDecoWork.MoveCapsuleExtraData(-1, i + 1, -1, i);
            }

            PlayerWork.playerParty.ReplaceMember((byte)lastIndex, copyParam);
            if (capsuleId >= 0)
                Dpr.BallDeco.BallDecoWork.SetAttachCapsule(capsuleId, copyParam.GetID(), copyParam.GetPersonalRnd(), -1, lastIndex);

            if (newPairIndex != -1 || pairIndex == fromIndex)
                SetPairPokemon(GetPartyPokemonParam(newPairIndex != -1 ? newPairIndex : lastIndex));

            if (IsRangeSwap())
                return;

            _hideIconIndexes.Clear();
            SetPartyLast(fromNavigator, navi =>
            {
                RestoreSelect(true, false, true, navi, null);
                FillPartyGap(fromNavigator, 1, true, null);
            });
        }
		private void SwapPartyByParty(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            int toIndex = (toNavigator.userParam as NaviParam).index;
            PlayerWork.playerParty.ExchangePosition((byte)fromIndex, (byte)toIndex);
            if (IsRangeSwap())
                return;

            RestoreSelect(true, true, true, null, null);
            SetTrayIconSwap(_swapIcons[1], toNavigator, fromNavigator, null);
        }
		private void BeginPartyByTray(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            if (GetNaviItem(toNavigator).pokemonParam != null)
                SwapPartyByTray(fromNavigator, toNavigator);
            else
                MoveLastPartyByTray(fromNavigator, toNavigator);
        }
		private void MoveLastPartyByTray(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromTrayIndex = _fromTrayIndex;
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            PokemonParam param = new PokemonParam(BoxPokemonWork.GetPokemon(fromTrayIndex, fromIndex));
            if (param.GetMonsNo() == MonsNo.SHEIMI)
                _effectIndexes.Add((int)PlayerWork.playerParty.GetMemberCount());

            Dpr.BallDeco.BallDecoWork.SwapCapsuleExtraData(fromTrayIndex, fromIndex, -1, (int)PlayerWork.playerParty.GetMemberCount());
            PlayerWork.playerParty.AddMember(param);
            BoxPokemonWork.ClearPokemon(fromTrayIndex, fromIndex);
            BoxWork.DeleteTeam(fromTrayIndex, fromIndex, true);
            if (IsRangeSwap())
                return;

            SetPartyLast(toNavigator, navi => RestoreSelect(true, _currentTrayIndex == fromTrayIndex, true, navi, null));
        }
		private void SwapPartyByTray(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromTrayIndex = _fromTrayIndex;
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            PokemonParam fromParam = BoxPokemonWork.GetPokemon(fromTrayIndex, fromIndex);
            int toIndex = (toNavigator.userParam as NaviParam).index;
            PokemonParam toParam = GetPartyPokemonParam(toIndex);
            uint battleCount = PlayerWork.playerParty.GetMemberCountEx(PokeParty.CountType.BATTLE_ENABLE);
            if (!CanBattlePokemon(fromParam) && (battleCount == 0 || (battleCount == 1 && CanBattlePokemon(toParam))))
            {
                SetMessage("SS_box_059");
                RestoreSelect(false, true, true, null, null);
                return;
            }

            ReturnPairPokemon(toParam);
            if (fromParam.GetMonsNo() == MonsNo.SHEIMI)
                _effectIndexes.Add(toIndex);

            PokemonParam copyParam = new PokemonParam(toParam);
            BoxWork.DeleteTeam(fromTrayIndex, fromIndex, true);
            BoxPokemonWork.UpdatePokemon(copyParam, fromTrayIndex, fromIndex);
            PlayerWork.playerParty.ReplaceMember((uint)toIndex, fromParam);
            Dpr.BallDeco.BallDecoWork.SwapCapsuleExtraData(fromTrayIndex, fromIndex, -1, toIndex);
            if (IsRangeSwap())
                return;

            RestoreSelect(true, true, true, null, null);
            if (_currentTrayIndex == fromTrayIndex)
            {
                _hideIconIndexes.Clear();
                _hideIconIndexes.Add(fromIndex);
                ApplyTray(false);
                SetTrayIconSwap(_swapIcons[1], toNavigator, fromNavigator, null);
            }
        }
		private void BeginTeamPartyByParty(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromTeamIndex = _fromTeamIndex;
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            int tray = BoxWork.GetTeamPokeBoxTray(fromTeamIndex, fromIndex);
            int pos = BoxWork.GetTeamPokeBoxPos(fromTeamIndex, fromIndex);
            int teamIndex = GetCurrentParty().Param.paramIndex;
            BoxItem naviItem = GetNaviItem(toNavigator);
            BoxWork.GetTeamPokeCount(teamIndex); // result unused (call kept @01ccabbc)
            bool isTeam = BoxWork.IsPokeTeam(tray, pos, teamIndex);
            if (naviItem.pokemonParam == null && !isTeam)
            {
                AddRegistTeam(fromNavigator, toNavigator);
                return;
            }

            if (isTeam)
            {
                int teamPos = BoxWork.GetPokeTeamPos(tray, pos, teamIndex);
                GetCurrentParty().Items[teamPos].SetIconDefault(false);
                fromNavigator = _battleTeam.GetNavigator(teamPos);
                _fromTeamIndex = teamIndex;
            }

            if (fromNavigator == toNavigator && _fromTeamIndex == teamIndex)
            {
                RestoreSelect(true, true, true, toNavigator, null);
                return;
            }

            if (naviItem.pokemonParam != null)
                SwapTeamPartyByParty(fromNavigator, toNavigator);
            else
                MoveLastTeamPartyByParty(fromNavigator, toNavigator);
        }
