		private void SwapTeamPartyByParty(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromTeamIndex = _fromTeamIndex;
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
