            int toPos = BoxWork.GetTeamPokeBoxPos(toTeamIndex, toIndex);
            BoxWork.SetTeamPokePos(toTeamIndex, toIndex, fromTray, fromPos);
            if (fromTeamIndex == toTeamIndex)
                BoxWork.SetTeamPokePos(fromTeamIndex, fromIndex, toTray, toPos);

            if (IsRangeSwap())
                return;

            RestoreSelect(true, true, true, null, null);
            _hideIconIndexes.Clear();
