		private void BeginRegistTeamByTray(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            BoxParty party = GetCurrentParty();
            int teamIndex = party.Param.paramIndex;
            BoxItem naviItem = GetNaviItem(toNavigator);
            int teamPos = BoxWork.GetPokeTeamPos(_fromTrayIndex, (fromNavigator.userParam as NaviParam).index, teamIndex);
            if (teamPos == BoxWork.TEAM_POKE_MAX)
            {
                if (naviItem.pokemonParam != null)
                    SwapRegistTeamByTray(fromNavigator, toNavigator);
                else
                    AddRegistTeam(fromNavigator, toNavigator);
            }
            else
            {
                party.Items[teamPos].SetIconDefault(false);
                if (naviItem.pokemonParam != null)
                    SwapAndPackRegistTeamByTray(fromNavigator, toNavigator);
                else
                    MoveLastTeamPartyByTray(fromNavigator, toNavigator);
            }
        }
		private void MoveLastTeamPartyByTray(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int toTeamIndex = GetCurrentParty().Param.paramIndex;
            int lastIndex = BoxWork.GetTeamPokeCount(toTeamIndex) - 1;
            int fromTrayIndex = _fromTrayIndex;
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            int fromIndexAtTeam = BoxWork.GetPokeTeamPos(fromTrayIndex, fromIndex, toTeamIndex);
            BoxWork.DeletePackTeam(toTeamIndex, fromIndexAtTeam);
            BoxWork.SetTeamPokePos(toTeamIndex, lastIndex, fromTrayIndex, fromIndex);
            if (IsRangeSwap())
                return;

            _hideIconIndexes.Clear();
            _hideIconIndexes.Add((toNavigator.userParam as NaviParam).index);
            SetPartyLast(toNavigator, navi =>
            {
                RestoreSelect(true, false, true, navi, null);
                _hideIconIndexes.Clear();
                _fromTeamIndex = toTeamIndex;
                FillPartyGap(_battleTeam.GetNavigator(fromIndexAtTeam), 1, true, () => ApplyTray(false));
            });
        }
		private void SwapAndPackRegistTeamByTray(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            BoxParty party = GetCurrentParty();
            int teamIndex = party.Param.paramIndex;
            int toIndex = (toNavigator.userParam as NaviParam).index;
            int toTray = BoxWork.GetTeamPokeBoxTray(teamIndex, toIndex);
            int toPos = BoxWork.GetTeamPokeBoxPos(teamIndex, toIndex);
            int fromTrayIndex = _fromTrayIndex;
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            int teamPos = BoxWork.GetPokeTeamPos(fromTrayIndex, fromIndex, teamIndex);
            // shipped @01cccd70: compares the team index against the tray index, not teamPos alone
            if (teamIndex != fromTrayIndex || teamPos != BoxWork.TEAM_POKE_MAX)
            {
                BoxWork.SetTeamPokePos(teamIndex, toIndex, fromTrayIndex, fromIndex);
                BoxWork.SetTeamPokePos(teamIndex, teamPos, toTray, toPos);
            }

            RestoreSelect(true, true, true, null, null);
            _hideIconIndexes.Clear();
            ApplyTray(false);
            SetTrayIconSwap(_swapIcons[1], toNavigator, party.GetNavigator(teamPos), null);
        }
		private void AddRegistTeam(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int teamIndex = GetCurrentParty().Param.paramIndex;
            NaviParam fromNaviParam = fromNavigator.userParam as NaviParam;
            int index = fromNaviParam.index;
            int tray;
            int pos;
            if (fromNaviParam.itemType == NaviParam.ItemType.Tray)
            {
                tray = _fromTrayIndex;
                pos = index;
            }
            else
            {
                tray = BoxWork.GetTeamPokeBoxTray(_fromTeamIndex, index);
                pos = BoxWork.GetTeamPokeBoxPos(_fromTeamIndex, index);
            }

            PokemonParam pokemonParam = BoxPokemonWork.GetPokemon(tray, pos);
            if (pokemonParam != null && pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
            {
                SetMessage("SS_box_103");
                RestoreSelect(false, true, true, null, null);
                return;
            }

            int count = _displayMode == DisplayMode.Battle ? BoxWork.GetTeamPokeCount(teamIndex) : (int)PlayerWork.playerParty.GetMemberCount();
            BoxWork.SetTeamPokePos(teamIndex, count, tray, pos);
            if (IsRangeSwap())
                return;

            SetPartyLast(toNavigator, navi =>
            {
                RestoreSelect(true, true, true, navi, null);
                _hideIconIndexes.Clear();
                ApplyTray(false);
            });
        }
