		private void UnregistTeam(global::Dpr.UI.UINavigator fromNavigator) {
            // shipped @01cc69a0: the team scroll param and the tray are fetched and never used
            BoxInfinityScrollItem.BaseParam teamParam = _battleTeamScroll.baseParams[_fromTeamIndex];
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            int fromTray = BoxWork.GetTeamPokeBoxTray(_fromTeamIndex, fromIndex);
            int count = BoxWork.GetTeamPokeCount(_fromTeamIndex);
            BoxWork.DeletePackTeam(_fromTeamIndex, fromIndex);
            if (IsRangeSwap())
                return;

            if (_fromTeamIndex == _battleTeam.Param.paramIndex)
                GetNaviItem(fromNavigator).SetIconDefault(false);

            _hideIconIndexes.Clear();
            RestoreSelect(true, false, false, null, null);
            if (fromIndex < count - 1)
                FillPartyGap(fromNavigator, 1, false, () => ApplyTray(true));
            else
                ApplyTray(true);
        }
		private void BeginTrayByParty(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            if (GetNaviItem(toNavigator).pokemonParam != null)
                SwapTrayByParty(fromNavigator, toNavigator);
            else
                MoveTrayByParty(fromNavigator, toNavigator);
        }
		private void MoveTrayByParty(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            PokemonParam fromParam = GetPartyPokemonParam(fromIndex);
            int toTrayIndex = _boxTray.Param.paramIndex;
            int toIndex = (toNavigator.userParam as NaviParam).index;
            int memberCount = _displayMode == DisplayMode.Battle ? BoxWork.GetTeamPokeCount(_fromTeamIndex) : (int)PlayerWork.playerParty.GetMemberCount();
            if (PlayerWork.playerParty.GetMemberCountEx(PokeParty.CountType.BATTLE_ENABLE) <= 1 && CanBattlePokemon(GetPartyPokemonParam(fromIndex)))
            {
                SetMessage("SS_box_059");
                RestoreSelect(false, true, true, null, null);
                return;
            }

            PokemonParam copyParam = new PokemonParam(fromParam);
            int pairIndex = GetPairPokemonIndex();
            if (pairIndex != -1 && pairIndex >= fromIndex)
                ReturnPairPokemon(GetPartyPokemonParam(pairIndex));

            int capsuleId = Dpr.BallDeco.BallDecoWork.GetAttachCapsuleId(fromParam.GetID(), fromParam.GetPersonalRnd(), -1, fromIndex);
            int lastIndex = memberCount - 1;
            if (fromIndex < lastIndex)
            {
                int newPairIndex = -1;
                for (int i = fromIndex; i < lastIndex; i++)
                {
                    PokemonParam next = GetPartyPokemonParam(i + 1);
                    PlayerWork.playerParty.ReplaceMember((byte)i, next);
                    if (pairIndex == i + 1)
                        newPairIndex = i;

                    Dpr.BallDeco.BallDecoWork.SwapCapsuleExtraData(-1, i + 1, -1, i);
                }

                if (newPairIndex != -1)
                    SetPairPokemon(GetPartyPokemonParam(newPairIndex));
            }

            PlayerWork.playerParty.RemoveMember((uint)lastIndex);
            BoxPokemonWork.PutPokemon(copyParam, toTrayIndex, toIndex);
            if (capsuleId >= 0)
                Dpr.BallDeco.BallDecoWork.SetAttachCapsule(capsuleId, copyParam.GetID(), copyParam.GetPersonalRnd(), toTrayIndex, toIndex);

            if (IsRangeSwap())
                return;

            RestoreSelect(true, false, true, null, null);
            _hideIconIndexes.Clear();
            FillPartyGap(fromNavigator, 1, false, () => ApplyTray(true));
        }
		private void SwapTrayByParty(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromIndex = (fromNavigator.userParam as NaviParam).index;
            PokemonParam fromParam = GetPartyPokemonParam(fromIndex);
            int toTrayIndex = _boxTray.Param.paramIndex;
            int toIndex = (toNavigator.userParam as NaviParam).index;
            PokemonParam toParam = BoxPokemonWork.GetPokemon(toTrayIndex, toIndex);
            uint battleCount = PlayerWork.playerParty.GetMemberCountEx(PokeParty.CountType.BATTLE_ENABLE);
            if (!CanBattlePokemon(toParam) && (battleCount == 0 || (battleCount == 1 && CanBattlePokemon(fromParam))))
            {
                SetMessage("SS_box_059");
                RestoreSelect(false, true, true, null, null);
                return;
            }

            ReturnPairPokemon(fromParam);
            if (toParam.GetMonsNo() == MonsNo.SHEIMI)
                _effectIndexes.Add(fromIndex);

            PokemonParam copyToParam = new PokemonParam(toParam);
            PokemonParam copyFromParam = new PokemonParam(fromParam);
            BoxWork.DeleteTeam(toTrayIndex, toIndex, true);
            PlayerWork.playerParty.ReplaceMember((uint)fromIndex, copyToParam);
            BoxPokemonWork.UpdatePokemon(copyFromParam, toTrayIndex, toIndex);
            Dpr.BallDeco.BallDecoWork.SwapCapsuleExtraData(-1, fromIndex, toTrayIndex, toIndex);
            if (IsRangeSwap())
                return;

            RestoreSelect(true, true, true, null, null);
            _hideIconIndexes.Clear();
            GetNaviItem(fromNavigator).Setup();
            SetTrayIconSwap(_swapIcons[1], toNavigator, fromNavigator, () => ApplyTray(true));
        }
		private void MoveItem(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromTrayIndex = _fromTrayIndex;
            NaviParam fromNaviParam = fromNavigator.userParam as NaviParam;
            BoxItem fromNaviItem = GetNaviItem(fromNavigator); // result unused (call kept @01cca170)
            int fromIndex = fromNaviParam.index;
            NaviParam toNaviParam = toNavigator.userParam as NaviParam;
            BoxItem toNaviItem = GetNaviItem(toNavigator);
            int toTrayIndex = toNaviParam.itemType == NaviParam.ItemType.Tray ? _boxTray.Param.paramIndex : GetCurrentParty().Param.paramIndex;
            int toIndex = toNaviParam.index;
            PokemonParam toPokemonParam = toNaviItem.pokemonParam;
            PokemonParam fromPokemonParam = fromNaviParam.itemType == NaviParam.ItemType.Tray ? BoxPokemonWork.GetPokemon(fromTrayIndex, fromIndex) : GetPartyPokemonParam(fromIndex);
            if (toPokemonParam.IsEgg(EggCheckType.BOTH_EGG))
            {
                Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
                SetMessage("SS_box_093");
                RestoreSelect(false, true, true, null, null);
                return;
            }

            toPokemonParam.SetItem(fromPokemonParam.GetItem());
            bool isToFormChange = SetFormChangeByItem(toPokemonParam);
            fromPokemonParam.RemoveItem();
            bool isFromFormChange = SetFormChangeByItem(fromPokemonParam);
            UpdatePokemonPaaram(fromTrayIndex, fromIndex, fromPokemonParam);
            UpdatePokemonPaaram(toTrayIndex, toIndex, toPokemonParam);
            if (fromTrayIndex >= 0 && fromTrayIndex != _boxTray.Param.paramIndex)
                isFromFormChange = false;

            RestoreSelectItem(isToFormChange, isFromFormChange, toNavigator, fromNavigator, toPokemonParam, fromPokemonParam);
        }
		private void SwapItem(global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator) {
            int fromTrayIndex = _fromTrayIndex;
            NaviParam fromNaviParam = fromNavigator.userParam as NaviParam;
            BoxItem fromNaviItem = GetNaviItem(fromNavigator);
            NaviParam toNaviParam = toNavigator.userParam as NaviParam;
            int fromIndex = fromNaviParam.index;
            int toTrayIndex = toNaviParam.itemType == NaviParam.ItemType.Tray ? _boxTray.Param.paramIndex : GetCurrentParty().Param.paramIndex;
            BoxItem toNaviItem = GetNaviItem(toNavigator);
            int toIndex = toNaviParam.index;
            PokemonParam fromPokemonParam = fromNaviParam.itemType == NaviParam.ItemType.Tray ? BoxPokemonWork.GetPokemon(fromTrayIndex, fromIndex) : GetPartyPokemonParam(fromIndex);
            PokemonParam toPokemonParam = toNaviItem.pokemonParam;
            if (toPokemonParam.IsEgg(EggCheckType.BOTH_EGG) || fromPokemonParam.IsEgg(EggCheckType.BOTH_EGG))
            {
                Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_BEEP, null);
                SetMessage("SS_box_093");
                RestoreSelect(false, true, true, null, null);
                return;
            }

            ushort fromItemNo = fromPokemonParam.GetItem();
            ushort toItemNo = toPokemonParam.GetItem();
            toPokemonParam.SetItem(fromItemNo);
            bool isToFormChange = SetFormChangeByItem(toPokemonParam);
            fromPokemonParam.SetItem(toItemNo);
            bool isFromFormChange = SetFormChangeByItem(fromPokemonParam);
            UpdatePokemonPaaram(fromTrayIndex, fromIndex, fromPokemonParam);
            UpdatePokemonPaaram(toTrayIndex, toIndex, toPokemonParam);
            if (fromTrayIndex >= 0 && fromTrayIndex != _boxTray.Param.paramIndex)
                isFromFormChange = false;

            RestoreSelectItem(isToFormChange, isFromFormChange, toNavigator, fromNavigator, toPokemonParam, fromPokemonParam);
            PokemonIcon fromIcon = GetNaviItem(fromNavigator).GetSwapRoot();
            PokemonIcon toIcon = toNaviItem.GetSwapRoot();
            if (fromTrayIndex == _currentTrayIndex || fromNaviParam.itemType != NaviParam.ItemType.Tray)
            {
                fromIcon.SwapItemIcon(toIcon);
                SetTrayIconSwap(_swapIcons[1], toNavigator, fromNavigator, () => fromNaviItem.SetItemState(true));
            }
        }
		private void RestoreSelect(bool isDecide = true, bool isUpdate = true, bool isFromHide = true, global::Dpr.UI.UINavigator toNavigator = null, global::System.Action callback = null) {
            if (isDecide)
            {
                _currentTrayIndex = _trayScroll.GetParamIndex();
                if (_displayMode == DisplayMode.Battle)
                    _currentTeamIndex = _battleTeamScroll.GetParamIndex();
            }

            if (toNavigator == null)
                toNavigator = _navigator;
            if (!isDecide)
                toNavigator = _fromNavigator;

            NaviParam naviParam = toNavigator.userParam as NaviParam;
            bool isParty = naviParam.itemType == NaviParam.ItemType.Party;
            if (isUpdate)
            {
                _hideIconIndexes.Clear();
                _hideIconIndexes.Add(naviParam.index);
                ApplyTray(isParty);
            }

            SetIconSelect(_swapIcon, toNavigator, false, isFromHide, () =>
            {
                if (_effectIndexes.Count > 0 && isDecide)
                {
                    _hideIconIndexes.Clear();
                    int index = _effectIndexes[0];
                    PokemonParam pokemonParam = GetPartyPokemonParam(index);
                    bool isPlay = SetFormChangeByMove(pokemonParam);
                    PlayFormChangeeffect(isPlay, pokemonParam, _partyNormal.Items[index].GetSwapRoot(), true, () =>
                    {
                        ApplyTray(true);
                        ApplyPokemonStatusAndModel(_navigator, false, true);
                    }, () =>
                    {
                        EndSwap(isParty);
                        callback?.Invoke();
                    });
                    return;
                }

                EndSwap(isParty);
                callback?.Invoke();
            });
        }
		private void RestoreSelectItem(bool isToChange, bool isFormChange, global::Dpr.UI.UINavigator toNavigator, global::Dpr.UI.UINavigator fromNavigator, global::Pml.PokePara.PokemonParam toPokemonParam, global::Pml.PokePara.PokemonParam fromPokemonParam) {
            _currentTrayIndex = _trayScroll.GetParamIndex();
            BoxItem fromNaviItem = GetNaviItem(fromNavigator);
            bool isFromParty = (fromNavigator.userParam as NaviParam).itemType == NaviParam.ItemType.Party;
            BoxItem toNaviItem = GetNaviItem(toNavigator);
            bool isToParty = (toNavigator.userParam as NaviParam).itemType == NaviParam.ItemType.Party;
            SetIconSelect(_swapIcon, toNavigator, false, true, () =>
            {
                _swapIcon.SetActive(true);
                PlayFormChangeeffect(isToChange, toPokemonParam, toNaviItem.GetSwapRoot(), true, () =>
                {
                    ApplyPokemonStatusAndModel(toNavigator, false, false);
                    toNaviItem.Setup();
                    toNaviItem.SetItemState(true);
                    _swapIcon.SetActive(false);
                }, () =>
                {
                    PlayFormChangeeffect(isFormChange, fromPokemonParam, fromNaviItem.GetSwapRoot(), true, () =>
                    {
                        ApplyTray(isFromParty);
                        fromNaviItem.SetItemState(true);
                    }, () => EndSwap(isToParty));
                });
            });
        }
		private void RestoreRangeSelect(bool isDecide = true, bool isUpdate = true, bool isFromHide = true, global::System.Collections.Generic.List<global::Dpr.UI.UINavigator> toNavigators = null, global::System.Action callback = null) {
            if (isDecide)
            {
                _currentTrayIndex = _trayScroll.GetParamIndex();
                if (_displayMode == DisplayMode.Battle)
                    _currentTeamIndex = _battleTeamScroll.GetParamIndex();
            }

            if (toNavigators == null)
                toNavigators = _toNavigators;

            NaviParam naviParam = (isDecide ? _toNavigators[0] : _fromNavigator).userParam as NaviParam;
            bool isParty = naviParam.itemType == NaviParam.ItemType.Party;
            if (isUpdate)
                ApplyTray(isParty);

            if (!isDecide)
            {
                toNavigators = _fromNavigators;
            }
            else if (isParty)
            {
                foreach (UINavigator navigator in toNavigators)
                {
                    if (GetNaviItem(navigator) is BoxPartyItem partyItem)
                        partyItem.ShowName(false);
                }
            }

            SetIconSelect(_swapIcons, toNavigators, false, isFromHide, () =>
            {
                if (_effectIndexes.Count < 1 || !isDecide)
                {
                    EndRangeSwap(isParty);
                    callback?.Invoke();
                    return;
                }

                _rangePlate.enabled = false;
                _hideIconIndexes.Clear();
                ApplyTray(true);
                for (int i = 0; i < _effectIndexes.Count; i++)
                {
                    int index = _effectIndexes[i];
                    PokemonParam pokemonParam = GetPartyPokemonParam(index);
                    bool isPlay = SetFormChangeByMove(pokemonParam);
                    bool isLast = i == _effectIndexes.Count - 1;
                    PlayFormChangeeffect(isPlay, pokemonParam, _partyNormal.Items[index].GetSwapRoot(), isLast, () =>
                    {
                        ApplyTray(true);
                        ApplyPokemonStatusAndModel(_navigator, false, true);
                    }, () =>
                    {
                        EndRangeSwap(isParty);
                        _rangePlate.enabled = true;
                        callback?.Invoke();
                    });
                }
            });
        }
		private void EndSwap(bool isParty) {
            _fromNavigator = null;
            _hideIconIndexes.Clear();
            _effectIndexes.Clear();
            ApplyTray(isParty);
            _currentTrayIndex = _boxTray.Param.paramIndex;
            _trayScroll.Apply(_currentTrayIndex, null, _param, _searchData, _selected);
            _boxListPanel.ApplyBox(_currentTrayIndex, _searchData);
            if (_fromTrayIndex >= 0 && _fromTrayIndex != _currentTrayIndex)
            {
                _trayScroll.Apply(_fromTrayIndex, null, _param, _searchData, _selected);
                _boxListPanel.ApplyBox(_fromTrayIndex, _searchData);
            }

            SetSearchButtonGray(false);
            SetCursorPattern(_operationType);
            SetTrayNamePlate(_navigator);
            _input.inputEnabled = true;
        }
		private void EndRangeSwap(bool isParty) {
            EndSwap(isParty);
            InitRangeSelect();
        }
