		private void FillPartyGap(global::Dpr.UI.UINavigator blankNavigator, int packCount = 1, bool isExceptLast = true, global::System.Action callback = null) {
            BoxParty party;
            int memberCount;
            if (_displayMode == DisplayMode.Battle)
            {
                party = _battleTeam;
                if (_fromTeamIndex != party.Param.paramIndex)
                {
                    callback?.Invoke();
                    return;
                }

                memberCount = BoxWork.GetTeamPokeCount(_fromTeamIndex);
            }
            else
            {
                party = _partyNormal;
                memberCount = (int)PlayerWork.playerParty.GetMemberCount();
            }

            int blankIndex = (blankNavigator.userParam as NaviParam).index;
            int moveCount = memberCount + packCount - (blankIndex + packCount) - (isExceptLast ? 1 : 0);
            List<Vector3> toPositions = new List<Vector3>();
            for (int i = 0; i < moveCount; i++)
            {
                int fromIndex = blankIndex + packCount + i;
                BoxPartyItem fromItem = party.Items[fromIndex];
                PokemonIcon fromIcon = fromItem.GetSwapRoot();
                fromIcon.SetActive(false);
                fromItem.ShowName(false);
                BoxPartyItem toItem = party.Items[blankIndex + i];
                toPositions.Add(toItem.GetSwapRoot().transform.position);
                // shipped: the capsule lookup reads the TO item's pokemon with the FROM slot index (w25 @01cc9e78)
                bool isBallDeco = toItem.pokemonParam != null && Dpr.BallDeco.BallDecoWork.GetAttachCapsuleId(toItem.pokemonParam.GetID(), toItem.pokemonParam.GetPersonalRnd(), -1, fromIndex) >= 0;
                _swapIcons[PartyMemberNum + i].transform.SetParent(_cursorCanvas.transform, false);
                _swapIcons[PartyMemberNum + i].SetActive(true);
                _swapIcons[PartyMemberNum + i].Copy(fromIcon);
                _swapIcons[PartyMemberNum + i].itemIcon.SetActive(false);
                _swapIcons[PartyMemberNum + i].ballDecoIcon.SetActive(isBallDeco);
                _swapIcons[PartyMemberNum + i].transform.position = fromItem.GetSwapRoot().transform.position;
                fromItem.GetSwapRoot().SetActive(false);
            }

            PokemonIcon[] targets = _swapIcons.GetRange(PartyMemberNum, moveCount).ToArray();
            _twSequence = SetIconMoveSequence(moveCount, targets, toPositions.ToArray(), () =>
            {
                for (int i = 0; i < moveCount; i++)
                    targets[i].SetActive(false);

                callback?.Invoke();
            });
        }
		private void SetIconSelect(global::Dpr.UI.PokemonIcon swapIcon, global::Dpr.UI.UINavigator navigator, bool isEnable, bool isFromHide, global::System.Action callback = null) {
