		private void SetIconSelect(global::System.Collections.Generic.List<global::Dpr.UI.PokemonIcon> swapIcons, global::System.Collections.Generic.List<global::Dpr.UI.UINavigator> navigators, bool isEnable, bool isFromHide, global::System.Action callback = null) {
            int count = navigators.Count;
            Vector3[] toPositions = new Vector3[count];
            Action onComplete = null;
            for (int i = 0; i < count; i++)
            {
                BoxItem naviItem = GetNaviItem(navigators[i]);
                if (naviItem == null)
                    continue;

                PokemonIcon targetIcon = naviItem.GetSwapRoot();
                if (isEnable)
                {
                    swapIcons[i].transform.position = targetIcon.transform.position;
                    if (naviItem.pokemonParam != null)
                    {
                        swapIcons[i].SetActive(true);
                        swapIcons[i].Copy(targetIcon);
                        swapIcons[i].monsIcon.SetActive(_displayMode != DisplayMode.Item);
                        swapIcons[i].itemIcon.SetActive(_displayMode == DisplayMode.Item && naviItem.pokemonParam.GetItem() != 0);
                        swapIcons[i].ballDecoIcon.SetActive(_displayMode != DisplayMode.Item && targetIcon.ballDecoIcon.IsActive());
                    }
                    else
                    {
                        swapIcons[i].SetActive(false);
                        swapIcons[i].itemIcon.SetActive(false);
                        swapIcons[i].ballDecoIcon.SetActive(false);
                    }

                    onComplete = () => callback?.Invoke();
#if !SWITCH
                    // the carry lift (56 UI units) in world pixels (PcUiRoot.UnitScale)
                    toPositions[i] = targetIcon.transform.position + BoxItem._moveIconOffset * PcPlatform.PcUiRoot.UnitScale(this);
#else
                    toPositions[i] = targetIcon.transform.position + BoxItem._moveIconOffset;
#endif
                }
                else
                {
                    onComplete = () =>
                    {
                        for (int j = 0; j < count; j++)
                        {
                            swapIcons[j].SetActive(false);
                            targetIcon.SetActive(true);
                        }

                        callback?.Invoke();
                    };
                    toPositions[i] = targetIcon.transform.position;
                }

                if (isFromHide)
                {
                    switch (_displayMode)
                    {
                        case DisplayMode.Arrangement:
                            if (isEnable || _swapIcons[i].monsIcon.sprite != null)
                                naviItem.SetIconDefault(false);
                            break;
                        case DisplayMode.Item:
                            naviItem.Select(false, false);
                            naviItem.GetSwapRoot().itemIcon.SetActive(false);
                            break;
                        case DisplayMode.Battle:
                        {
                            BoxPartyItem partyItem = naviItem as BoxPartyItem;
                            if (isEnable)
                            {
                                if (partyItem == null)
                                {
                                    naviItem.Select(true, true);
                                }
                                else
                                {
                                    partyItem.SelectOnlyIcon(true, true);
                                    partyItem.ShowName(false);
                                }
                            }
                            else
                            {
                                naviItem.SetIconDefault(false);
                                partyItem?.ShowName(false);
                            }
                            break;
                        }
                    }
                }
            }

            _twSequence = SetIconMoveSequence(count, swapIcons.ToArray(), toPositions, onComplete);
        }
		private void SetTrayIconSwap(global::Dpr.UI.PokemonIcon swapIcon, global::Dpr.UI.UINavigator fromNavigator, global::Dpr.UI.UINavigator toNavigator, global::System.Action callback = null) {
            bool isItemMode = _displayMode == DisplayMode.Item;
            BoxItem fromNaviItem = GetNaviItem(fromNavigator);
            fromNaviItem.SetIconDefault(false);
            PokemonIcon fromIcon = fromNaviItem.GetSwapRoot();
            fromIcon.SetActive(isItemMode);
            fromIcon.itemIcon.SetActive(false);
            BoxItem toNaviItem = GetNaviItem(toNavigator);
            toNaviItem.SetIconDefault(false);
            bool isToExist = toNaviItem.pokemonParam != null;
            PokemonIcon toIcon = toNaviItem.GetSwapRoot();
            toIcon.SetActive(isItemMode);
            toIcon.itemIcon.SetActive(false);
            bool isBallDeco = isToExist && Dpr.BallDeco.BallDecoWork.GetAttachCapsuleId(toNaviItem.pokemonParam.GetID(), toNaviItem.pokemonParam.GetPersonalRnd(), _currentTrayIndex, toNaviItem.Index) >= 0;
            swapIcon.transform.SetParent(_cursorCanvas.transform, false);
            swapIcon.transform.position = fromIcon.transform.position;
            swapIcon.SetActive(true);
            swapIcon.Copy(toIcon);
            swapIcon.monsIcon.SetActive(!isItemMode);
            swapIcon.itemIcon.SetActive(isItemMode && isToExist && toNaviItem.pokemonParam.GetItem() != 0);
            swapIcon.ballDecoIcon.SetActive(isBallDeco && !isItemMode);
            _twSequence = SetIconMoveSequence(swapIcon, toIcon.transform.position, () =>
            {
                swapIcon.SetActive(false);
                if (isToExist)
                    toIcon.SetActive(true);

                callback?.Invoke();
            });
        }
		public static global::DG.Tweening.Sequence SetIconMoveSequence(global::Dpr.UI.PokemonIcon fromIcon, global::UnityEngine.Vector3 toPosition, global::System.Action callback = null) {
            return SetIconMoveSequence(1, new PokemonIcon[] { fromIcon }, new Vector3[] { toPosition }, callback);
        }
		public static global::DG.Tweening.Sequence SetIconMoveSequence(int count, global::Dpr.UI.PokemonIcon[] fromIcons, global::UnityEngine.Vector3[] toPositions, global::System.Action callback = null) {
            if (count == 0)
                return null;

            DG.Tweening.Sequence sequence = DOTween.Sequence().OnComplete(() => callback?.Invoke());
            for (int i = 0; i < count; i++)
                sequence.Join(fromIcons[i].transform.DOMove(toPositions[i], _pokeIconDuration, false));

            sequence.SetLink(fromIcons[0].gameObject).Play();
            return sequence;
        }
