		private bool SetFormChangeByItem(global::Pml.PokePara.PokemonParam pokemonParam) {
            ushort formNo = pokemonParam.GetFormNo();
            ushort nextFormNo = pokemonParam.GetNextFormNoFromHoldItem(pokemonParam.GetItem());
            if (nextFormNo == formNo)
                return false;

            pokemonParam.ChangeFormNo(nextFormNo, null);
            ZukanWork.SetPoke(pokemonParam, DPData.GET_STATUS.GET);
            if (FieldManager.fwMng != null)
                FieldManager.fwMng.CheckPartnerPokeChange(pokemonParam, false);

            return true;
        }
		private bool SetFormChangeByMove(global::Pml.PokePara.PokemonParam pokemonParam) {
            if (pokemonParam.GetMonsNo() != MonsNo.SHEIMI || pokemonParam.GetFormNo() == 0)
                return false;

            pokemonParam.ChangeFormNo(0, null);
            if (FieldManager.fwMng != null)
                FieldManager.fwMng.CheckPartnerPokeChange(pokemonParam, false);

            return true;
        }
		private void PlayFormChangeeffect(bool isPlay, global::Pml.PokePara.PokemonParam pokemonParam, global::Dpr.UI.PokemonIcon pokeIcon, bool isSingle = true, global::System.Action onChangeIcon = null, global::System.Action onComplete = null) {
            MonsNo monsNo = pokemonParam.GetMonsNo();
            if (isPlay && (monsNo == MonsNo.GIRATHINA || monsNo == MonsNo.SHEIMI))
            {
                if (isSingle)
                    _isControlEnable = false;

                int effectIndex = monsNo == MonsNo.GIRATHINA ? 9 : 8;
                uint seId = monsNo == MonsNo.GIRATHINA ? 0x2c68d66cu : 0x554b01f4u;
                EffectManager.LoadParam loadParam = EffectManager.Instance.dbEffects.MenuEffetData[effectIndex];
                EffectManager.Instance.Load(new EffectManager.LoadParam[] { loadParam }, (effectData, isAllLoaded) =>
                {
                    int count = 2;

                    void Complete()
                    {
                        if (isCancelFormChange)
                            return;

                        count--;
                        if (count > 0)
                            return;

                        UIDatabase.SheetPokemonVoice voiceData = UIManager.Instance.GetPokemonVoiceData(monsNo, pokemonParam.GetFormNo(), pokemonParam.GetSex(), pokemonParam.GetRareType(), false);
                        // shipped @01a24ad4: no voice event = neither onComplete nor _isControlEnable is restored
                        if (string.IsNullOrEmpty(voiceData.WwiseEvent))
                            return;

                        uint playEventId = Audio.AudioManager.Instance.GetIdByName(voiceData.WwiseEvent);
                        uint stopEventId = Audio.AudioManager.Instance.GetIdByName(voiceData.stopEventId);
                        Action callback = () =>
                        {
                            onComplete?.Invoke();
                            _isControlEnable = true;
                        };
                        Audio.AudioManager.Instance.PlayVoice(playEventId, stopEventId, audioInstance =>
                        {
                            if (isCancelFormChange)
                                return;

                            if (monsNo == MonsNo.SHEIMI || monsNo == MonsNo.GIRATHINA)
                            {
                                MessageWordSetHelper.SetPokemonNickNameWord(0, pokemonParam, true);
                                SetMessage("ss_bag", "SS_bag_146", true, callback, null, false);
                            }
                            else
                            {
                                callback();
                            }
                        });
                    }

                    _formChangeEffectInstance = EffectManager.Instance.Play(effectData, pokeIcon.transform.position, Quaternion.identity, null, instance =>
                    {
                        if (isCancelFormChange)
                            return;

                        if (isSingle)
                            Complete();

                        instance.RestoreTransformParent();
                    });
                    if (_effectRoot != null)
                        _formChangeEffectInstance.SetTransformParent(_effectRoot, true);

                    if (isSingle)
                        Audio.AudioManager.Instance.PlaySe(seId, audioInstance => Complete());

                    IEnumerator EffectProc()
                    {
                        yield return new WaitForSeconds(0.8f);
                        if (!isCancelFormChange)
                            onChangeIcon?.Invoke();
                    }

                    SmartPoint.AssetAssistant.Sequencer.Start(EffectProc());
                });
            }
            else
            {
                onChangeIcon?.Invoke();
                onComplete?.Invoke();
            }
        }
		private bool CanBattlePokemon(global::Pml.PokePara.PokemonParam param) {
            if (param == null || param.IsEgg(EggCheckType.BOTH_EGG))
