		public static bool IsHitSearchType(global::Pml.PokePara.PokemonParam pokemonParam, global::Dpr.UI.BoxWindow.SEARCH_DATA data, int tray = 40, int pos = 30) {
            if (data == null || !data.is_active)
                return true;

            BoxMarkContainer markContainer = new BoxMarkContainer();
            pokemonParam.GetAllBoxMark(markContainer);
            bool isHit = true;
            for (int i = 0; i < markContainer.markColor.Length; i++)
            {
                int mark = (data.mark >> (i * 2)) & 3;
                if (mark != 0 && mark != (int)markContainer.markColor[i])
                {
                    isHit = false;
                    break;
                }
            }

            if (pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
            {
                return isHit && data.mons == MonsNo.NULL && data.type1 == PokeType.NULL && data.type2 == PokeType.NULL && data.waza == WazaNo.NULL &&
                    data.waza_machine == 0x7FFFFFFF && data.tokusei == TokuseiNo.NULL && data.seikaku == Seikaku.NUM && data.sex == Sex.NUM &&
                    data.item == SearchItem.MAX && data.team == BoxWork.TEAM_MAX;
            }

            isHit &= pokemonParam.GetMonsNo() == data.mons || data.mons == MonsNo.NULL;
            PokeType type1 = pokemonParam.GetType1();
            PokeType type2 = pokemonParam.GetType2();
            if (data.type1 != type1 && data.type1 != type2)
                isHit &= data.type1 == PokeType.NULL;

            if (data.type2 != type1 && data.type2 != type2)
                isHit &= data.type2 == PokeType.NULL;

            if (data.waza != WazaNo.NULL)
                isHit &= pokemonParam.HaveWaza(data.waza);

            if (data.waza_machine != 0x7FFFFFFF)
                isHit &= pokemonParam.CheckWazaMachine((uint)data.waza_machine);

            isHit &= pokemonParam.GetTokuseiNo() == data.tokusei || data.tokusei == TokuseiNo.NULL;
            isHit &= pokemonParam.GetSeikaku() == data.seikaku || data.seikaku == Seikaku.NUM;
            isHit &= data.sex == pokemonParam.GetSex() || data.sex == Sex.NUM;
            isHit &= data.item == (pokemonParam.GetItem() != 0 ? SearchItem.YES : SearchItem.NO) || data.item == SearchItem.MAX;
            if (data.team != BoxWork.TEAM_MAX)
                isHit = isHit && tray < BoxWork.TRAY_MAX && (pos >= BoxWork.TRAY_POKE_MAX || BoxWork.IsPokeTeam(tray, pos, data.team));

            return isHit;
        }
		public static bool IsHitSelectType(global::Pml.PokePara.PokemonParam pokemonParam, global::Dpr.UI.BoxWindow.OpenParam param) {
            MonsNo monsNo = pokemonParam.GetMonsNo();
            bool isHit = false;
            if (param.targetsPokeNo == null)
            {
                isHit = true;
            }
            else if (!pokemonParam.IsEgg(EggCheckType.BOTH_EGG))
            {
                for (int i = 0; i < param.targetsPokeNo.Length; i++)
                {
                    if (param.targetsPokeNo[i] == 0)
                        break;

                    if ((int)monsNo == param.targetsPokeNo[i])
                    {
                        isHit = true;
                        break;
                    }
                }
            }

            bool isLevel = pokemonParam.GetLevel() >= param.targetLevel;
            return isHit & isLevel;
        }
