		public class SEARCH_DATA
		{
			public global::Pml.MonsNo mons;
			public global::Pml.PokeType type1;
			public global::Pml.PokeType type2;
			public global::Pml.WazaNo waza;
			public int waza_machine;
			public global::Pml.TokuseiNo tokusei;
			public global::Pml.PokePara.Seikaku seikaku;
			public global::Pml.Sex sex;
			public global::Dpr.UI.BoxWindow.SearchItem item;
			public int mark;
			public int team;
			public int form;
			public bool is_active;
			public SEARCH_DATA()
            {
                type1 = PokeType.NULL;
                type2 = PokeType.NULL;
                sex = Sex.NUM;
                waza = WazaNo.NULL;
                waza_machine = 0x7FFFFFFF;
                tokusei = TokuseiNo.NULL;
                seikaku = Seikaku.NUM;
                item = SearchItem.MAX;
                mark = 0;
                mons = MonsNo.NULL;
                team = BoxWork.TEAM_MAX;
                form = 0;
                is_active = false;
            }
			public void Clear()
            {
                type1 = PokeType.NULL;
                type2 = PokeType.NULL;
                waza = WazaNo.NULL;
                waza_machine = 0x7FFFFFFF;
                tokusei = TokuseiNo.NULL;
                seikaku = Seikaku.NUM;
                sex = Sex.NUM;
                item = SearchItem.MAX;
                mark = 0;
                mons = MonsNo.NULL;
                is_active = false;
                team = BoxWork.TEAM_MAX;
                form = 0;
            }
			public void SetActive() {
                is_active = mons != MonsNo.NULL || type1 != PokeType.NULL || type2 != PokeType.NULL || waza != WazaNo.NULL || waza_machine != 0x7FFFFFFF ||
                    tokusei != TokuseiNo.NULL || seikaku != Seikaku.NUM || sex != Sex.NUM || item != SearchItem.MAX || mark != 0 || team != BoxWork.TEAM_MAX ||
                    form != 0;
            }
		}
